/* EMBERHOLLOW CAVE — hunts against monster packs. Each depth unlocks at a level;
   monsters fight at your level (never below the depth's minimum). A hunt is one
   battle with full HP; it pays XP and gold and counts toward bounties. */
const CAVE = { name: 'Emberhollow Cave' };
const CAVE_DEPTHS = [
  { id: 'tunnels', name: 'Smoke Tunnels', minLv: 1, size: 3, scale: 1, pool: ['cinderbat', 'ashcrawler', 'magmaslime'],
    desc: 'Warm upper tunnels full of bats, spiders and slow, burning slimes.' },
  { id: 'grotto', name: 'Glowcap Grotto', minLv: 4, size: 4, scale: 1.05, pool: ['ashcrawler', 'magmaslime', 'bonerattler', 'glowcap'],
    desc: 'A glowing cavern where mushroom shamans keep the dead miners on their feet.' },
  { id: 'den', name: "Troll's Den", minLv: 8, size: 4, scale: 1.05, pool: ['bonerattler', 'glowcap', 'magmaslime', 'cinderbat'], elite: 'cavetroll',
    desc: 'The deepest chamber. A Cave Troll and whatever it lets live down there.' },
];
const depthById = (id) => CAVE_DEPTHS.find((d) => d.id === id);
const HUNT_GOLD_BASE = 10, HUNT_GOLD_PER = 6;   // gold per hunt: base + per monster

// A pack: the depth's elite (if any) plus random monsters from its pool, at most one shaman.
function rollPack(d) {
  const pack = d.elite ? [d.elite] : [];
  while (pack.length < d.size) {
    const id = pick(d.pool);
    if (id === 'glowcap' && pack.includes('glowcap')) continue;
    pack.push(id);
  }
  return pack;
}

/* ==================================================================
   DUNGEONS — expeditions from the Expedition Gate. A run is DG_ROOM_COUNT
   rooms (monster packs) and then a boss room: 7 battles in all. The first
   rooms are the dungeon's own `rooms`; the rest are rolled from the same
   monsters when you set out (state.dg.plan). HP, MP and skill cooldowns carry
   over between rooms: fallen champions get back up at 30%, and everyone catches their
   breath a little. Each room pays XP and gold; the boss guards a chest,
   and the first clear of each dungeon also gives a trinket.
   Every room fields a full war party of DG_PACK_MIN–DG_PACK_MAX monsters:
   the authored packs are grown to size with extra bodies from the same
   dungeon, never stacking a second healer on a pack that already has one.
   Wounded minions flee: the moment a monster's HP falls to a quarter
   (DG_FLEE_AT) it runs deeper into the dungeon, without waiting for its own
   turn (fleeWounded, after every action and turn-start) — the first DG_FLEE_CAP
   to break are the only ones who go, never in the boss room, and each
   monster only once. The warband chases straight into the next room,
   where the runaways rejoin the new pack still wounded.
   Abandoning the run keeps everything earned so far.
   Monsters fight at your level, never below the dungeon's minimum.
   ================================================================== */
/* DUNGEON CONDITIONS — a standing rule for every room of a run. Unlike weather it never
   rotates and never lifts: it is the place itself. Shown on the dungeon's card at the
   Expedition Gate, announced in each room's log, and named in the battle's pill.
   Not every dungeon has one (the Spire, Direhold and the Hollow run plain for now). */
const DG_CONDS = {
  damp: { icon: '💧', name: 'Grave Damp', brief: 'Everyone fights Soaked.',
          desc: 'The water never drained out of the abbey. Everyone counts as Soaked: Ironclad Heat is doused and cannot build, and lightning deals 30% more to the soaked.' },
  gas:  { icon: '🔥', name: 'Firedamp',   brief: 'Burn deals 50% more.',
          desc: 'Gas pools in the old shafts and catches on anything alight. Burn deals 50% more to everyone, yours and theirs alike.' },
  haunt:{ icon: '👻', name: 'Haunting',   brief: 'One fighter per side is Hexed each room.',
          desc: 'The house takes an interest in its guests. At the start of every room one fighter on each side is Hexed: all healing they receive is halved until something cleanses it.' },
};

/* PER-ROOM HAZARDS — Castle Harrowgate's battlefields each keep their own trouble
   (roomConds, one entry per room). Two are schedules rather than hazards:
   'ruincycle' rotates round by round — Earthquake (the cave's bar-jolts), Falling
   Rocks, Red Fog, repeat — and 'ballroom' runs Red Fog, a chandelier crash, Red Fog
   over rounds 1–3, then falls calm for the kill. hazardRound applies each round's
   hazard; hazardPace slows the bar under falling debris (allies 25%, enemies 15% —
   the household knows where not to stand). */
const DG_HAZARDS = {
  redfog:      { icon: '🌫️', name: 'Red Fog', brief: 'The fog works on everyone: each round, 30% to be Poisoned and 20% to be Blinded.' },
  rockfall:    { icon: '⛰️', name: 'Falling Rocks', brief: 'Debris rains: allies cross the bar 25% slower, the household 15%.' },
  chandeliers: { icon: '🕯️', name: 'Falling Chandeliers', brief: 'The fittings are coming down: allies 25% slower, the household 15% — and some of them land.' },
  quakephase:  { icon: '🪨', name: 'Earthquake', brief: 'The columns groan: the whole bar is thrown back a step, again and again.' },
};
const dgRoomCond = () => dungeonRun()?.roomConds?.[state.dg.room] || null;
function dgHazard() {
  const c = dgRoomCond();
  if (!c) return null;
  if (c === 'ruincycle') return ['quakephase', 'rockfall', 'redfog'][(state.round - 1) % 3];
  if (c === 'ballroom') return state.round === 2 ? 'chandeliers' : state.round <= 3 ? 'redfog' : null;
  return c;
}
const hazardIs = (id) => dgHazard() === id;
const hazardPace = (u) => (hazardIs('rockfall') || hazardIs('chandeliers')) ? (u.side === 'p' ? 0.75 : 0.85) : 1;

// A chandelier (or a slab of the ruin) comes down: n random fighters are Stunned for a round.
// The hallway drops them on the warband alone; the Ballroom is impartial — but never the lord.
function crashChandeliers(n, bothSides) {
  const pool = shuffle(allUnits().filter((u) => alive(u) && !u.inert && !u.boss && (bothSides || u.side === 'p')));
  for (const u of pool.slice(0, n)) {
    burst(u, 'smoke');
    float(u, '💥 Chandelier', 'fx');
    addFx(u, 'stun', 1);
    log(`A chandelier comes down on ${u.name}: stunned for a round.`, 'sys');
  }
}

// Applies the room's hazard as each round opens (round 1 comes via applyDgCond).
function hazardRound() {
  const d = dungeonRun();
  if (!d?.roomConds) return;
  const hz = dgHazard();
  // The Ruin Columns' quake round borrows the cave's machinery: state.quake drives the bar jolts.
  state.quake = hz === 'quakephase' ? 1 : 0;
  state.quakeJolt = hz === 'quakephase' ? state.time + QUAKE_EVERY : null;
  if (!hz) return;
  const H = DG_HAZARDS[hz];
  log(`${H.name}: ${H.brief}`, 'wx');
  if (hz === 'redfog') for (const u of allUnits()) {
    if (!alive(u) || u.inert) continue;
    if (chance(0.3)) addFx(u, 'poison', 3, Math.max(3, Math.round(u.maxHp * 0.035)));
    if (chance(0.2)) addFx(u, 'blind', 2);
  }
  if (hz === 'chandeliers' && state.round === 2) crashChandeliers(dgRoomCond() === 'ballroom' ? 3 : 2, dgRoomCond() === 'ballroom');
}

