// The town map's viewBox is 0 0 2400 1400, a bird's-eye view (see TOWN MAP): map units → % of its width and height.
const MAP_X0 = 0, MAP_W = 2400, MAP_H = 1400;
const MAP_HOME = [1200, 820];   // where the first look at the village lands: the square's bonfire
const MAP_AR = MAP_W / MAP_H;   // the view is this many times wider than tall; the pan/zoom math uses it
document.documentElement.style.setProperty('--map-ar', `${MAP_W} / ${MAP_H}`);
const mapX = (x) => `${((x - MAP_X0) / MAP_W * 100).toFixed(2)}%`, mapY = (y) => `${(y / MAP_H * 100).toFixed(2)}%`;
const linesOf = (list) => list.map((l) => (typeof l === 'function' ? l() : l)).filter(Boolean);

