/* The light of the lifted cross: a cone of grave-green poured from the head of the cross onto the
   target, swelling as the iron heats (0.36 -> hit) and lingering a moment after, with the target
   lit green at the moment it lands. ms = the whole move's length, hit = its impact fraction. */
function graveShine(u, t, ms, hit) {
  const a = stageBox(u), b = stageBox(t);
  if (reduced || !a || !b) return;
  const d = facing(u);
  const from = { x: a.x + d * a.w * 0.42, y: a.top + a.h * 0.16 };   // the crossing of the lifted cross
  const to = { x: b.x, y: b.top + b.h * 0.5 };
  const len = Math.hypot(to.x - from.x, to.y - from.y) + b.w * 0.25;
  const ang = Math.atan2(to.y - from.y, to.x - from.x) * 180 / Math.PI;
  const el = document.createElement('div');
  el.className = 'graveshine';
  Object.assign(el.style, { left: `${from.x}px`, top: `${from.y}px`, width: `${len}px`, height: `${Math.max(b.h * 0.9, 50)}px`,
    transform: `translateY(-50%) rotate(${ang}deg)` });
  el.innerHTML = '<i></i>';
  $('#arena').appendChild(el);
  const life = ms * 1.25;
  el.animate([{ opacity: 0 }, { opacity: 0, offset: 0.36 / 1.25 }, { opacity: 1, offset: hit / 1.25 }, { opacity: 0.85, offset: 0.86 / 1.25 }, { opacity: 0 }],
    { duration: life, fill: 'forwards' });
  setTimeout(() => el.remove(), life + 60);
  setTimeout(() => {
    burst(t, 'grave');
    bodyEl(t)?.animate([{ filter: 'none' }, { filter: 'brightness(1.35) drop-shadow(0 0 12px rgba(126, 230, 150, .95))', offset: 0.3 }, { filter: 'none' }],
      { duration: beat(700) });
  }, ms * hit);
}

/* HEAD LASER (Spanner Swing): a close-range red beam from Orin's head to the target.
   He is already standing in melee range, so the beam is short and instant — a camera-flash
   of red light that sears across, with the target lit red at impact. */
function headLaser(u, t, ms, hit) {
  const a = stageBox(u), b = stageBox(t);
  if (reduced || !a || !b) return;
  const d = facing(u);
  const from = { x: a.x + d * a.w * 0.15, y: a.top + a.h * 0.22 };
  const headY = b.top + b.h * 0.08;
  const feetY = b.feet - 2;
  const angHead = Math.atan2(headY - from.y, b.x - from.x) * 180 / Math.PI;
  const angFeet = Math.atan2(feetY - from.y, b.x - from.x) * 180 / Math.PI;
  const maxLen = Math.hypot(b.x - from.x, feetY - from.y) + 12;
  const el = document.createElement('div');
  Object.assign(el.style, {
    position: 'absolute', left: `${from.x}px`, top: `${from.y}px`,
    width: `${maxLen}px`, height: '60px', marginTop: '-30px',
    background: 'linear-gradient(90deg, rgba(226,80,80,0) 0%, rgba(226,80,80,.7) 10%, #fff2f2 40%, #ffffff 50%, #fff2f2 60%, rgba(226,80,80,.7) 90%, rgba(226,80,80,0) 100%)',
    boxShadow: '0 0 14px rgba(226,80,80,.95), 0 0 36px rgba(200,60,60,.6), 0 0 60px rgba(226,80,80,.3)',
    borderRadius: '0 12px 12px 0', transformOrigin: '0 50%', pointerEvents: 'none',
    clipPath: 'polygon(0 46%, 100% 0%, 100% 100%, 0 54%)',
    zIndex: '9999',
  });
  $('#arena').appendChild(el);
  const beamStart = 0.14;
  const beamEnd = 0.88;
  const beamMs = ms * (beamEnd - beamStart);
  el.animate([
    { transform: `rotate(${angHead}deg)`, opacity: 0 },
    { transform: `rotate(${angHead}deg)`, opacity: 0, offset: beamStart - 0.02 },
    { transform: `rotate(${angHead}deg)`, opacity: 1, offset: beamStart },
    { transform: `rotate(${angFeet}deg)`, opacity: 1, offset: beamEnd },
    { transform: `rotate(${angFeet}deg)`, opacity: 0, offset: beamEnd + 0.04 },
    { transform: `rotate(${angFeet}deg)`, opacity: 0 },
  ], { duration: ms, fill: 'forwards' });
  setTimeout(() => el.remove(), ms + 60);
  const tb = bodyEl(t);
  if (tb) {
    const glowStart = ms * beamStart;
    tb.animate([
      { filter: 'none' },
      { filter: 'brightness(1.5) drop-shadow(0 0 12px rgba(226, 80, 80, .95))', offset: 0.15 },
      { filter: 'brightness(1.3) drop-shadow(0 0 8px rgba(226, 80, 80, .7))', offset: 0.85 },
      { filter: 'none' },
    ], { duration: beamMs, delay: glowStart });
  }
  setTimeout(() => burst(t, 'hit'), ms * hit);
}

/* WELD BEAM (Hammer Weld): a green healing laser from Orin's head sweeping the ally
   head-to-toe. Same geometry as headLaser but green and aimed at a friend. Returns a
   promise that resolves when the beam finishes so healSkill can wait on it. */
function weldBeam(u, t) {
  const a = stageBox(u), b = stageBox(t);
  if (reduced || !a || !b) return Promise.resolve();
  const d = facing(u);
  const from = { x: a.x + d * a.w * 0.15, y: a.top + a.h * 0.22 };
  const headY = b.top + b.h * 0.08;
  const feetY = b.feet - 2;
  const angHead = Math.atan2(headY - from.y, b.x - from.x) * 180 / Math.PI;
  const angFeet = Math.atan2(feetY - from.y, b.x - from.x) * 180 / Math.PI;
  const maxLen = Math.hypot(b.x - from.x, feetY - from.y) + 12;
  const ms = 1800;
  const el = document.createElement('div');
  Object.assign(el.style, {
    position: 'absolute', left: `${from.x}px`, top: `${from.y}px`,
    width: `${maxLen}px`, height: '60px', marginTop: '-30px',
    background: 'linear-gradient(90deg, rgba(103,208,138,0) 0%, rgba(103,208,138,.7) 10%, #e0ffe8 40%, #ffffff 50%, #e0ffe8 60%, rgba(103,208,138,.7) 90%, rgba(103,208,138,0) 100%)',
    boxShadow: '0 0 14px rgba(103,208,138,.95), 0 0 36px rgba(80,180,120,.6), 0 0 60px rgba(103,208,138,.3)',
    borderRadius: '0 12px 12px 0', transformOrigin: '0 50%', pointerEvents: 'none',
    clipPath: 'polygon(0 46%, 100% 0%, 100% 100%, 0 54%)',
    zIndex: '9999',
  });
  $('#arena').appendChild(el);
  el.animate([
    { transform: `rotate(${angHead}deg)`, opacity: 0 },
    { transform: `rotate(${angHead}deg)`, opacity: 1, offset: 0.06 },
    { transform: `rotate(${angFeet}deg)`, opacity: 1, offset: 0.88 },
    { transform: `rotate(${angFeet}deg)`, opacity: 0, offset: 0.95 },
    { transform: `rotate(${angFeet}deg)`, opacity: 0 },
  ], { duration: ms, fill: 'forwards' });
  const bod = bodyEl(u);
  if (bod) bod.animate([
    { transform: 'none' },
    { transform: `translateY(-6px) translateX(${d * 4}px)`, offset: 0.08 },
    { transform: `translateY(-3px) translateX(${d * 5}px) rotate(${d * 2}deg)`, offset: 0.20 },
    { transform: `translateY(-7px) translateX(${d * 4}px)`, offset: 0.35 },
    { transform: `translateY(-2px) translateX(${d * 5}px) rotate(${d * 3}deg)`, offset: 0.50 },
    { transform: `translateY(-6px) translateX(${d * 4}px)`, offset: 0.65 },
    { transform: `translateY(-2px) translateX(${d * 5}px) rotate(${d * 2}deg)`, offset: 0.80 },
    { transform: `translateX(${d * 3}px)`, offset: 0.90 },
    { transform: 'none' },
  ], { duration: ms });
  const tb = bodyEl(t);
  if (tb) tb.animate([
    { filter: 'none' },
    { filter: 'brightness(1.4) drop-shadow(0 0 12px rgba(103, 208, 138, .9))', offset: 0.15 },
    { filter: 'brightness(1.3) drop-shadow(0 0 8px rgba(103, 208, 138, .7))', offset: 0.85 },
    { filter: 'none' },
  ], { duration: ms * 0.82, delay: ms * 0.06 });
  return new Promise((r) => { setTimeout(() => { el.remove(); r(); }, ms + 60); });
}

/* Who has an authored swing, by champion — 'ryuunosuke:Twin Slash' counts for
   ryuunosuke. syncHeldWeapon reads this to decide whether to inline their art:
   the poses below swing `.wpn`, and those pieces only exist as elements once
   the file is in the DOM rather than behind an <img>. Built once, after every
   WEAPON_STRIKES entry above has been assigned. */
const STRIKE_RIGGED = new Set(Object.keys(WEAPON_STRIKES).map((k) => k.split(':')[0]));
const hasStrikeArt = (id) => STRIKE_RIGGED.has(id);

// Weapon swing: lean in and twist, or the champion's own attack clip. Resolves at the moment of impact.
// sk (optional) = the skill being swung: a basic Attack can use the champion's WEAPON_STRIKES move.
// pace < 1 runs the same swing through quicker, for flurries that would drag at full length.
async function strikePose(u, fresh = false, sk = null, pace = 1, tg = null) {
  const d = facing(u);
  // A skill's own move ('barrow:Tomb Slab') first, then the champion's basic-Attack move.
  const ws = sk && (WEAPON_STRIKES[`${u.id}:${sk.name}`] || (sk.id === 'attack' && WEAPON_STRIKES[u.id]));
  // Skip pre-rendered clips when a skill-specific WEAPON_STRIKES entry exists.
  if (!ws || !(sk && WEAPON_STRIKES[`${u.id}:${sk.name}`])) {
    const hit = playAttack(u, fresh, sk);
    if (hit != null) return sleep(hit * pace);
  }
  /* Every .wpn piece, not just the first. A swapped weapon is one group and this
     is the same as it ever was, but a champion drawn holding their own is marked
     piece by piece to keep the artist's z-order (see WEARING WHAT YOU CARRY) —
     Ryuunosuke's katana is nine. Swinging only the first sent the blade across
     the field and left the guard, the wrap and the pommel standing in his hand. */
  if (ws && !reduced && u.hp > 0) {
    const ms = beat(ws.ms * pace);
    const parts = [...(bodyEl(u)?.querySelectorAll('.wpn') || [])];
    if (parts.length) {
      parts.forEach((p) => p.animate(ws.wpn, { duration: ms }));
      if (ws.off) bodyEl(u).querySelector('.wpn2')?.animate(ws.off, { duration: ms });
    }
    pose(u, ws.body(d), ws.ms * pace);
    if (ws.shine && tg) graveShine(u, tg, ms, ws.hit);
    if (ws.laser && tg) headLaser(u, tg, ms, ws.hit);
    await sleep(ms * ws.hit);
    return;
  }
  if (!pose(u, [{ transform: 'none' }, { transform: `translateX(${d * 14}px) rotate(${d * 12}deg)`, offset: 0.4 }, { transform: 'none' }], 240)) return;
  await sleep(beat(100));
}

// Ranged wind-up: a small recoil before the shot.
async function aimPose(u, sk = null) {
  const hit = playAttack(u, false, sk);
  if (hit != null) return sleep(hit);
  const d = facing(u);
  if (!pose(u, [{ transform: 'none' }, { transform: `translateX(${-d * 6}px) rotate(${-d * 4}deg)`, offset: 0.5 }, { transform: 'none' }], 260)) return;
  await sleep(beat(120));
}

/* Spells, buffs, summons, guard and potions: a hop with a golden glow.
   `clip` plays the champion's own attack animation instead, which suits a skill they
   perform — a heal, a ward, a summon — but not raising a guard or drinking a draught. */
async function castPose(u, clip = false, sk = null) {
  const hit = clip ? playAttack(u, false, sk) : null;
  if (hit != null) return sleep(hit);
  if (!pose(u, [{ transform: 'none', filter: 'none' },
    { transform: 'translateY(-12px)', filter: 'brightness(1.4) drop-shadow(0 0 8px #e8a548)', offset: 0.4 },
    { transform: 'none', filter: 'none' }], 420)) return;
  await sleep(beat(200));
}

/* RAISING THE FALLEN (revive skills: Mortessa's Second Burial). She walks over to the body and
   chants — her hair blown outward, her eyes blazing green, grave-light pulsing over the corpse —
   then the fallen ally rises slowly back onto their feet with eyes lit bright green.
   The revive itself happens at the moment they begin to stand (onRise). */
const EYE_SPOTS = {};   // art id → [{ x, y }] eye positions in the 100x100 art box
async function eyeSpots(u) {
  const id = artOf(u);
  if (EYE_SPOTS[id]) return EYE_SPOTS[id];
  // Built-in sprites are drawn inline; file art is read from the SVG itself.
  let svg = bodyEl(u)?.querySelector('.upic > svg');
  if (!svg && ART_FOLDER[u.faction]) {
    try {
      const txt = await (await fetch(`characters/${ART_FOLDER[u.faction]}/${id}.${ART_EXT}`)).text();
      svg = new DOMParser().parseFromString(txt, 'image/svg+xml').documentElement;
    } catch { svg = null; }
  }
  // Eyes = small round shapes in the head's height band; the front-most (champions face right) wins.
  const found = [];
  svg?.querySelectorAll('circle, ellipse').forEach((c) => {
    const r = +(c.getAttribute('r') || c.getAttribute('ry') || 0), x = +c.getAttribute('cx'), y = +c.getAttribute('cy');
    if (r >= 0.8 && r <= 3.4 && y >= 12 && y <= 46 && x >= 42 && x <= 72) found.push({ x, y });
  });
  found.sort((a, b) => b.x - a.x);
  const eyes = found.length ? found.filter((e) => Math.abs(e.y - found[0].y) < 4 && found[0].x - e.x < 11).slice(0, 2) : [{ x: 57, y: 30 }];
  return (EYE_SPOTS[id] = eyes);
}
async function lightEyes(u) {
  const host = bodyEl(u)?.querySelector('.upic');
  if (!host) return;
  const eyes = await eyeSpots(u), flip = u.side === 'e';   // enemies are drawn mirrored
  const el = document.createElement('div');
  el.className = 'eyeglow';
  el.innerHTML = eyes.map((e) => `<i style="left:${flip ? 100 - e.x : e.x}%;top:${e.y}%"></i>`).join('');
  host.appendChild(el);
  setTimeout(() => el.remove(), beat(3000));
}
async function raiseRitual(u, t, onRise) {
  if (!t) return;   // nobody to raise: never leave the turn hanging
  const trip = t !== u ? await dashTo(u, [t]) : null;   // walk over to the body
  const b = bodyEl(u), ms = beat(1500);
  if (!reduced && b) {
    // Hair blown outward on a grave-wind, fluttering; eyes flare bright green.
    b.querySelectorAll('.hair').forEach((h) => {
      const out = h.classList.contains('hair-r') ? -1 : 1;
      h.animate([{ transform: 'rotate(0deg)' }, { transform: `rotate(${out * 34}deg) scaleX(1.12)`, offset: 0.2 },
        { transform: `rotate(${out * 26}deg) scaleX(1.08)`, offset: 0.4 }, { transform: `rotate(${out * 38}deg) scaleX(1.14)`, offset: 0.6 },
        { transform: `rotate(${out * 28}deg) scaleX(1.1)`, offset: 0.8 }, { transform: 'rotate(0deg)' }], { duration: ms, easing: 'ease-in-out' });
    });
    b.querySelectorAll('.eyelight').forEach((e) => e.animate([{ fill: '#8ee6a0', transform: 'scale(1)', filter: 'none' },
      { fill: '#f2fff4', transform: 'scale(2)', filter: 'drop-shadow(0 0 1.6px #6ff09a)', offset: 0.2 },
      { fill: '#f2fff4', transform: 'scale(2)', filter: 'drop-shadow(0 0 1.6px #6ff09a)', offset: 0.85 },
      { fill: '#8ee6a0', transform: 'scale(1)', filter: 'none' }], { duration: ms }));
    pose(u, [{ filter: 'none', transform: 'none' }, { filter: 'drop-shadow(0 0 6px #6ff09a)', transform: 'translateY(-3px)', offset: 0.25 },
      { filter: 'drop-shadow(0 0 8px #6ff09a)', transform: 'translateY(-3px)', offset: 0.85 }, { filter: 'none', transform: 'none' }], 1500);
    // The incantation: grave-light pulses over the body three times.
    for (const k of [0.05, 0.35, 0.65]) setTimeout(() => burst(t, 'grave'), ms * k);
  }
  await sleep(reduced ? 0 : ms * 0.75);
  // The rise: slow the fallen body's stand-up transition, then bring them back.
  const tb = bodyEl(t);
  // The body stands up slowly, but the death-grey and fade clear almost at once, so the green-lit
  // eyes (inside the body) shine at full strength through the whole rise.
  if (tb && !reduced) tb.style.transition = `transform ${beat(1400)}ms ease-out, opacity ${beat(250)}ms ease-out, filter ${beat(250)}ms ease-out`;
  onRise();
  render();
  lightEyes(t);
  await sleep(reduced ? 0 : ms * 0.25);
  await dashBack(u, trip);
  await sleep(reduced ? 0 : beat(1400) * 0.6 + beat(200));   // let them finish standing
  if (tb) tb.style.transition = '';
}

// Getting hit: knocked back toward its own side, flashing white. Crits hit harder and shake the field.
function knock(t, crit) {
  burst(t, 'hit');
  const back = -facing(t);
  pose(t, [{ transform: 'none', filter: 'none' },
    { transform: `translateX(${back * (crit ? 18 : 10)}px) rotate(${back * (crit ? 8 : 4)}deg)`, filter: 'brightness(2.2)', offset: 0.25 },
    { transform: 'none', filter: 'none' }], crit ? 380 : 280);
  if (crit && !reduced) $('#arena').animate([{ translate: '0 0' }, { translate: '5px -3px' }, { translate: '-4px 3px' }, { translate: '0 0' }], { duration: beat(260) });
}

// Dodging: a quick hop backward.
function dodgeHop(t) {
  const back = -facing(t);
  pose(t, [{ transform: 'none' }, { transform: `translate(${back * 22}px, -10px)`, offset: 0.4 }, { transform: 'none' }], 320);
}

function burst(u, kind) {
  const b = bodyEl(u);
  if (!b) return;
  const el = document.createElement('div');
  el.className = `burst burst-${kind}`;
  b.appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

// What a ranged attack throws. Skills and basic attacks with their own look are listed in
// PROJ_SKILL (by skill name) and PROJ_ATTACK (by unit id); everything else falls back to the
// attacker's weapon. kind = CSS class / PROJ_ART key. arc: true = lobbed and tumbling,
// 'curve' = lobbed nose-first. upright = never rotated (music notes). impact = burst on arrival
// ('boom' = fire + smoke).
/* Named lifts for the two throwers whose whole identity is the throw, so a tweak lands in one place
   instead of across the six entries each of them owns. Both are requests, not promises: the lob
   clamps them to whatever headroom the arena actually has (see ARC_CEILING_MARGIN).
   Drekka throws pots overhand and they tumble, so she gets the heavier arc. Vashka's javelins fly
   nose-first and flatter — a spear lobbed as high as a bomb stops reading as a spear. */
const DREKKA_LIFT = 420;
const VASHKA_LIFT = 320;
const PROJ_ATTACK = {
  // The shell holds its nose to the arc ('curve') rather than tumbling: a
  // fired round is spin-stabilised, and an oblong one that cartwheels reads as
  // something dropped. Drekka's bomb keeps tumbling — a thrown keg should.
  arclight: { kind: 'spark' }, howitzer: { kind: 'shell', arc: 'curve' },
  // Drekka lobs everything overhand, so her whole kit throws high (her skill pots below carry the
  // same lift). Asking past a short arena's ceiling is fine — the lob clamps it (ARC_CEILING_MARGIN).
  drekka: { kind: 'bomb', arc: true, impact: 'smoke', lift: DREKKA_LIFT },
  aldous: { kind: 'fireball', impact: 'fire' }, seraphine: { kind: 'bubble' }, octavia: { kind: 'inkball' },
  // Patchwork mends at range, so he throws light rather than hardware (.proj-beam).
  // Elowen sends a bird, and it banks on the way (arc: 'curve' flies
  // nose-first along the parabola, so it leads with its beak). The lift is
  // shallow — a bird crossing a field, not a lobbed stone.
  patchwork: { kind: 'beam' }, elowen: { kind: 'bird', arc: 'curve', lift: 54 },
  maren: { kind: 'pearl' }, faelan: { kind: 'xbolt' },
  scrapbot: { kind: 'laser' }, illusion: { kind: 'inkball' },   // the turret fires light, not rivets (.proj-laser)
  // Old Mother Hesk throws a grasping hand of red light, not a bead (.proj-hand).
  // Green fire, so the colour that rides along is green too.
  hesk: { kind: 'pyreskull', color: '#8ce05a' },
  mara: { kind: 'silver' },   // a thin silver round, out of a barrel that flashes fire and smoke (MUZZLE)
  cadris: { kind: 'firefly', wander: true },   // his basic attack sends a small green grave-firefly, drifting every which way before it strikes
  riven: { kind: 'lightsword', impact: 'light', swordThrow: true }, shazrak: { kind: 'sonicpulse' }, nyx: { kind: 'voidbolt' }, automatonx: { kind: 'redbeam' },
  /* Vashka throws her spears rather than thrusting them, so they leave on an arc instead of flat.
     Hers by name and not on `case 'spear'` down in projectileFor: that case is shared with a trident
     and with a human spear champion, who hold their weapons rather than throw them — lobbing it
     there would launch a braced polearm across the field. 'curve' rather than true so the javelin
     flies point-first along the arc instead of tumbling end over end like Vaun's skull. */
  vashka: { kind: 'spear', arc: 'curve', lift: VASHKA_LIFT },
};
const PROJ_SKILL = {
  // Ironclad Union
  'Overclock': { kind: 'greenball', impact: 'heal' },
  'Discharge': { kind: 'plasma' },
  'Flak Burst': { kind: 'flak', arc: true, impact: 'flak' },
  'Siege Shell': { kind: 'rocket', arc: 'curve', impact: 'boom' },
  'AP Round': { kind: 'missile', impact: 'fire' },
  'Beam Burst': { kind: 'laser' },   // the Scrapbot's three-round burst (keyed by skill name)
  // Bloodtusk Horde
  // Vashka's throws, all on the same nose-first arc as her basic (see vashka in PROJ_ATTACK).
  // Pinning Throw and Volley are listed only to ARC them: without an entry they fall through to
  // `case 'spear'`, which is flat and shared with champions who never let go of the shaft.
  "Hunter's Mark": { kind: 'dart', arc: 'curve', lift: VASHKA_LIFT },
  'Gutpiercer': { kind: 'javelin', arc: 'curve', lift: VASHKA_LIFT },
  'Pinning Throw': { kind: 'javelin', arc: 'curve', lift: VASHKA_LIFT },
  'Volley of Spears': { kind: 'javelin', arc: 'curve', lift: VASHKA_LIFT },
  'Firepot': { kind: 'firepot', arc: true, impact: 'fire', lift: DREKKA_LIFT },
  'Molotov': { kind: 'molotov', arc: true, impact: 'fire', lift: DREKKA_LIFT },
  'Napalm Jar': { kind: 'napalm', arc: true, impact: 'fire', lift: DREKKA_LIFT },
  'Powder Keg': { kind: 'keg', arc: true, impact: 'boom', lift: DREKKA_LIFT },
  /* Shrapnel Bomb is the one pot of hers with no fire in it, so it must not reach the 'pot'
     catch-all in projectileFor — that hands every unlisted throw of Drekka's a fire projectile
     and a fire impact. It flies as flak (the same burst Howitzer's Flak Burst uses) on her own
     lift, so it reads as nails rather than flame. */
  'Shrapnel Bomb': { kind: 'flak', arc: true, impact: 'flak', lift: DREKKA_LIFT },
  // Kingdom of Aldmere
  'Aimed Shot': { kind: 'tracer' },
  'Powder Shot': { kind: 'slug', impact: 'smoke' },
  'Ricochet': { kind: 'ricochet' },
  'Fireball': { kind: 'fireball', impact: 'fire' },
  'Ignite': { kind: 'flare', impact: 'fire' },
  'Inferno': { kind: 'meteor', arc: 'curve', impact: 'boom' },
  // Stoneleaf Accord
  'Swift Arrows': { kind: 'swiftarrow' },
  'Hawkeye': { kind: 'hawkarrow' },
  'Arrow Rain': { kind: 'arrow', arc: 'curve' },
  'Venom Bolt': { kind: 'venombolt' },
  'Thornvolley': { kind: 'thorn', arc: 'curve' },
  'Envenom': { kind: 'toxarrow', impact: 'curse' },
  'Entangle': { kind: 'vine' },
  // The Tideborn
  "Siren's Hush": { kind: 'note', upright: true },
  'Lure Song': { kind: 'heartnote', upright: true },
  'Dirge of the Deep': { kind: 'dirge', upright: true, impact: 'curse' },
  'Rimefall': { kind: 'shard', arc: 'curve', impact: 'ice' },   // lobbed high and comes down point-first
  'Ink Cloud': { kind: 'inkcloud', arc: true, impact: 'ink' },
  'Tentacle Snare': { kind: 'inkjet' },
  // The Crimson Court
  'Blight Hex': { kind: 'hexorb', impact: 'curse' },
  'Blood Siphon': { kind: 'bloodbolt' },
  // The Pale Host
  'Scatter of Bones': { kind: 'bloodbones', arc: true },   // Vaun flings a fistful of broken, bloody ribs
  // The Riftborn
  'Ray': { kind: 'lightray' },
  'Prism Lance': { kind: 'prismlance' },
  'Glare': { kind: 'glareshot', impact: 'light' },
  'Clarion': { kind: 'sonicpulse', impact: 'sound' },
  'Thrum': { kind: 'thrum', impact: 'sound' },
  'Discord': { kind: 'discordwave', impact: 'sound' },
  'Null Bolt': { kind: 'voidbolt', impact: 'void' },
  'Unmake': { kind: 'voidlance', impact: 'void' },
  'Silencing Gyre': { kind: 'voidgyre', impact: 'void' },
  'Collapse Point': { kind: 'voidbolt', impact: 'void' },
  'Attune: Gravity': { kind: 'attuneg', impact: 'gravity' },
  'Attune: Light': { kind: 'attunel', impact: 'light' },
  'Attune: Void': { kind: 'attunev', impact: 'void' },
  'Grand Chord': { kind: 'discordwave', impact: 'sound' },
  'Steady Tone': { kind: 'sonicpulse' },
  // Stray
  'Mark of Death': { kind: 'kunai' },
  // Neutral skills (when a ranged champion equips them)
  'Throwing Axe': { kind: 'axe', arc: true },
  'Flash Powder': { kind: 'flash', arc: true, impact: 'flash' },
  'Scattershot': { kind: 'pellets' },
  'Caltrops': { kind: 'caltrop', arc: true },
};

// SVG art for projectiles CSS can't draw: [width, height, markup], in px, pointing right.
const PI_ = 'stroke="#15121d" stroke-width=".8"';
const arrowArt = (tip, fletch, shaft = '#8a5a32', extra = '', x = 0) => `${extra}
  <line x1="${x + 2}" y1="4" x2="${x + 24}" y2="4" stroke="${shaft}" stroke-width="2"/>
  <path d="M${x + 23} 1 L${x + 32} 4 L${x + 23} 7 Z" fill="${tip}" ${PI_}/>
  <path d="M${x} .5 L${x + 6} 4 L${x} 7.5 L${x + 2} 4 Z" fill="${fletch}"/>`;
// A crossbow bolt: short, thick shaft, broad head, stubby vanes.
const boltArt = (tip, vane, extra = '') => `${extra}
  <line x1="2" y1="4" x2="17" y2="4" stroke="#6b4630" stroke-width="2.6"/>
  <path d="M16 .8 L24 4 L16 7.2 Z" fill="${tip}" ${PI_}/>
  <path d="M0 1.5 L5 4 L0 6.5 Z" fill="${vane}" ${PI_}/>`;
