function projectileFor(u, sk) {
  const o = sk.o || {}, a = lookOf(artOf(u)) || {};
  const own = sk.id === 'attack' ? PROJ_ATTACK[u.id] : PROJ_SKILL[sk.name];
  if (own) return own;
  // Riven throws nothing but his own swords: every skill of his flies as the same blade his Attack does.
  if (u.maxSwords) return PROJ_ATTACK[u.id] || PROJ_ATTACK.riven;
  if (o.element === 'lightning') return { kind: 'bolt' };
  // Drekka is the only champion who carries a pot, so this catch-all is hers: it takes her lift too,
  // and without it Cinder Spray would be the one throw in her kit that didn't go high.
  if (a.weapon === 'pot') return { kind: 'fire', arc: true, lift: DREKKA_LIFT };
  if ((o.fx || []).some(([id]) => id === 'burn')) return { kind: 'fire' };
  if (a.body === 'bot') return { kind: 'bullet' };
  switch (a.weapon) {
    case 'bow': return { kind: 'arrow' };
    case 'crossbow': return { kind: 'xbolt' };
    case 'gun': return a.orb ? { kind: 'orb', color: a.orb } : { kind: 'bullet' };
    case 'cannon': return { kind: 'shell', arc: 'curve' };   // nose-first, not tumbling — see PROJ_ATTACK.howitzer
    /* Vaun: the staff is the lever, so every shot is a skull thrown high in a tumbling arch, and this
       asks for more arc than a short arena can hold ON PURPOSE.
       The ceiling it is asking past is real, and was measured before this clamp existed: a quadratic
       peaks at HALF its control offset, and .arena is overflow: hidden with aspect-ratio 16/8 and
       min-height 330px, so a shooter in a high back slot has only ~180px of headroom on a 400px
       arena — past roughly that the skull is CUT at the top edge mid-flight rather than merely
       flying high. The old answer was to pick one timid number (420) that survived the worst slot on
       the shortest screen, and let every other shot pay for it.
       It no longer has to: the lob clamps this request to whatever headroom the field actually has
       (see ARC_CEILING_MARGIN), so ask high and take what fits. That is also why this no longer has
       to move alongside the arena — it follows the arena on its own. */
    case 'slingstaff': return { kind: 'skullshot', arc: true, lift: 560 };
    // A hand sling off the arm alone: the same skull, a flatter throw. No champion carries one as
    // their base weapon since Vaun moved to the staff - WEAPONS.sling lives on as the Ribcage
    // Sling's gear art, and equipping that only changes what is DRAWN (the look built in gearUp is
    // local), never what flies. Kept so the mapping is right the day someone does carry one.
    case 'sling': return { kind: 'skullshot', arc: true, lift: 170 };
    case 'spear': case 'trident': return { kind: 'spear' };
    default: return { kind: 'orb', color: a.orb || '#9fe08a' };
  }
}

/* Skill-stamped stage effects (skill options wave / quake / slash): Hellfire Slam's rolling
   fire ring, Ground Pound's tremor, Power Slash's crescent. All purely visual. */

// A ring of pit-fire rolling out from the slam point across the ground in every direction.
function fireWave(u) {
  const b = stageBox(u), arena = $('#arena');
  if (reduced || !b || !arena) return;
  const d = arena.getBoundingClientRect().width * 1.15;   // wide enough to roll past the farthest fighter
  const el = document.createElement('div');
  el.className = 'firewave';
  el.style.cssText = `left:${b.x.toFixed(1)}px; top:${(b.feet - 4).toFixed(1)}px; width:${d.toFixed(0)}px; height:${(d * 0.34).toFixed(0)}px; margin:${(-d * 0.17).toFixed(0)}px 0 0 ${(-d / 2).toFixed(0)}px;`;
  arena.appendChild(el);
  el.addEventListener('animationend', (e) => { if (!e.pseudoElement) el.remove(); });
  setTimeout(() => el.remove(), 1400);   // in case animations never run
}

// Graveside Chill: a green grave-wind sweeps across the enemy line, left to right. Each fighter it
// passes chills with a grave-burst; the hits themselves land back in damageSkill as the wind clears.
async function graveGust(u, targets) {
  const arena = $('#arena'), boxes = targets.map(stageBox).filter(Boolean);
  if (reduced || !arena || !boxes.length) { await sleep(reduced ? 0 : 240); return; }
  const left = Math.min(...boxes.map((b) => b.x)), right = Math.max(...boxes.map((b) => b.x));
  const top = Math.min(...boxes.map((b) => b.top)), bot = Math.max(...boxes.map((b) => b.feet));
  const w = Math.max(160, right - left + 220), h = Math.max(120, bot - top + 64), ms = beat(1600);
  const dir = facing(u);   // +1 blows to the right, -1 to the left: the wind follows its caster
  const el = document.createElement('div');
  el.className = 'gravegust';
  el.style.cssText = `left:${(left - 110).toFixed(0)}px; top:${(top - 32).toFixed(0)}px; width:${w.toFixed(0)}px; height:${h.toFixed(0)}px; --gust-ms:${ms}ms; --gust-dir:${dir};`;
  arena.appendChild(el);
  el.addEventListener('animationend', (e) => { if (!e.pseudoElement) el.remove(); });
  setTimeout(() => el.remove(), ms + 400);
  // The cold reaches each fighter in turn as the wind rolls past: the one nearest the caster
  // first, so the order reverses with the wind rather than always running left to right.
  const order = targets.filter(stageBox).sort((a, b) => (stageBox(a).x - stageBox(b).x) * dir);
  const gap = ms * 0.55 / Math.max(order.length, 1);
  for (const t of order) { burst(t, 'grave'); await sleep(gap); }
  await sleep(beat(160));
}

/* THE SLAM. Bulwark drives both fists into the floor and a ring runs out from
   where they land, flat along the ground in every direction.

   Centred on the SLAMMER'S feet, not on the mark — it is the floor carrying
   it, so it starts where he is standing and washes over whoever is near. The
   `left` + negative `margin-left` pairing is the fire ring's: it centres a box
   that has to keep growing from its middle. */
function slamWave(u, { size = 1, ms = 780 } = {}) {
  const b = stageBox(u), arena = $('#arena');
  if (reduced || !b || !arena) return;
  const d = arena.getBoundingClientRect().width * 0.62 * size;
  const dur = beat(ms);
  const el = document.createElement('div');
  el.className = 'slamwave';
  el.style.cssText = `left:${b.x.toFixed(1)}px; top:${(b.feet - 4).toFixed(1)}px; width:${d.toFixed(0)}px; height:${(d * 0.34).toFixed(0)}px; margin:${(-d * 0.17).toFixed(0)}px 0 0 ${(-d / 2).toFixed(0)}px; --wave-ms:${dur}ms;`;
  arena.appendChild(el);
  el.addEventListener('animationend', (e) => { if (!e.pseudoElement) el.remove(); });
  setTimeout(() => el.remove(), dur + 300);
}

/* One slam: PUNCH the floor — feet planted, fists driven down. The ring goes
   as they LAND rather than on the wind-up; a wave that leaves early reads as
   a miss.

   The first cut lifted the whole body 11px on the wind-up and dropped it, and
   that one negative translateY was enough to read as a little jump. A machine
   this heavy does not hop to hit the ground: it rocks back, then pitches
   FORWARD over its fists. So the wind-up is a backward lean with no lift at
   all, and the strike is a forward rotation plus a hard vertical squash — the
   body folding over the blow. The only downward travel is the few pixels of
   recoil after the fists have already arrived. */
async function groundSlam(u, size) {
  const d = facing(u);
  const ok = pose(u, [{ transform: 'none' },
    { transform: `rotate(${-d * 7}deg) scaleY(1.05)`, offset: 0.28, easing: 'ease-out' },
    { transform: `rotate(${-d * 8}deg) scaleY(1.06)`, offset: 0.38 },
    { transform: `translateY(6px) rotate(${d * 11}deg) scaleY(.84)`, offset: 0.55, easing: 'cubic-bezier(.6,0,1,.4)' },
    { transform: `translateY(3px) rotate(${d * 5}deg) scaleY(.93)`, offset: 0.72 },
    { transform: 'none' }], 560);   // pose() applies beat() itself — do not pre-scale it
  if (!ok) { slamWave(u, { size }); return; }
  await sleep(beat(300));          // land first
  slamWave(u, { size });
  tremorFx(beat(380));             // this one takes raw ms, so it DOES want beat()
  burst(u, 'smoke');
  await sleep(beat(230));
}

/* TWICE. The second is wider than the first: a pair of identical rings reads
   as one effect stuttering, where a bigger second reads as him putting more
   into it. The gap between them is deliberately short — this is one action,
   not two swings. */
async function doubleSlam(u) {
  await groundSlam(u, 0.82);
  await groundSlam(u, 1.15);
}

/* THE PUNCH RING. A ring of shoved air where a fist landed.

   Keyed off the WEAPON, not off Bulwark. He is the only champion in the game
   who fights with his hands, so this is his alone today — but it belongs to
   punching rather than to him, and the next bare-handed champion gets it for
   free by being drawn with fists. A `u.id === 'bulwark'` test would have been
   the same thing written so that it only ever works once.

   Upright and narrow because the shock runs along the line of the blow: you
   are seeing the ring edge-on. It blooms on the side the fist came from, so it
   reads as coming off the knuckles rather than out of the target's chest. */
const punches = (u) => !u.summon && !u.monster && charById(u.id)?.look?.weapon === 'fist';

/* One ring. `size` and `ms` are what separate the ordinary swing from Piston
   Punch: the same drawing, scaled up and held open longer.

   This briefly stacked three delayed copies for Piston Punch, on the theory
   that a wave of them would read as weight. It did not — three rings crowding
   one body read as clutter, and one big ring says "that landed hard" more
   plainly. The knob is gone rather than left unused. */
function punchRing(u, t, { size = 1, ms = 360 } = {}) {
  const arena = $('#arena'), b = stageBox(t);
  if (reduced || !arena || !b) return;
  // Sized off the unit it lands on, so a ring on a boss is a boss-sized ring.
  // The floor matters as much as the ratio: on a small target the ratio alone
  // produced a ring smaller than the fist that made it.
  const tall = Math.max(58, (b.feet - b.top) * 0.78) * size;
  const wide = tall * 0.46;
  const dir = facing(u);                               // which way the blow travelled
  const cx = b.x - dir * wide * 0.55;                  // back toward the fist
  const cy = b.feet - (b.feet - b.top) * 0.58;         // chest height, where a punch lands
  const dur = beat(ms);
  /* A big ring on a front-row target hangs off the bottom of the field: the
     blow lands at chest height, and half of 200-odd px of ring is more than
     the ground has under it. Clipped at the arena's edge it reads as a drawing
     fault rather than a heavy hit, so the ring slides up to stay whole. It
     moves rather than shrinks — the size is the point of it. */
  const arenaH = arena.getBoundingClientRect().height;
  const top = Math.max(4, Math.min(cy - tall / 2, arenaH - tall - 4));
  const el = document.createElement('div');
  el.className = 'punchring';
  el.style.cssText = `left:${(cx - wide / 2).toFixed(1)}px; top:${top.toFixed(1)}px; width:${wide.toFixed(0)}px; height:${tall.toFixed(0)}px; --ring-ms:${dur}ms;`;
  arena.appendChild(el);
  el.addEventListener('animationend', (e) => { if (!e.pseudoElement) el.remove(); });
  setTimeout(() => el.remove(), dur + 300);
}

/* STEAM VENT. Bulwark-7 cracks its valves at the far line and the pressure
   goes somewhere: a jet leaves the vents, reaches the enemy warband, and boils
   up over all of them at once.

   The cloud is sized off the TARGETS rather than off a fixed radius, the way
   graveGust is — so it covers the warband wherever the warband happens to be
   standing, and a line of four spread across the field gets a wide bank of
   steam while a last survivor gets a small one. A fixed box would be right
   exactly once.

   The jet is drawn from the vents to the near edge of that box and rotated
   onto the line between them, so it points wherever the enemy actually is and
   works just as well with the sides reversed (an enemy Bulwark venting left).
   Steam cannot be a projectile here: it has to arrive everywhere at once. */
async function steamVent(u, targets) {
  const arena = $('#arena'), from = stageBox(u);
  const boxes = targets.map(stageBox).filter(Boolean);
  if (reduced || !arena || !from || !boxes.length) { await sleep(reduced ? 0 : 200); return; }

  const left = Math.min(...boxes.map((b) => b.x)), right = Math.max(...boxes.map((b) => b.x));
  const top = Math.min(...boxes.map((b) => b.top)), bot = Math.max(...boxes.map((b) => b.feet));
  // Generous of the warband's own box: steam spreads, and a cloud that stopped
  // exactly at the outermost shoulder would read as a rectangle, not a gas.
  const cw = Math.max(220, (right - left) + 260), ch = Math.max(150, (bot - top) + 120);
  const cx = (left + right) / 2, cy = (top + bot) / 2;
  /* A longer release. The valves hold open rather than cracking once: the jet
     sustains instead of flashing, and the bank lingers over the line long
     enough to read as a vent emptying rather than a puff. */
  const ms = beat(1850), jetMs = beat(760);

  // The jet: from the tip of Bulwark's barrel to the near edge of the cloud.
  const d = facing(u);
  const vx = from.x + d * from.w * 0.48, vy = from.feet - (from.feet - from.top) * 0.28;
  const toX = cx - Math.sign(cx - vx) * (cw / 2) * 0.55;
  const len = Math.max(40, Math.abs(toX - vx));
  const ang = d > 0 ? 0 : 180;
  const jet = document.createElement('div');
  jet.className = 'steamjet';
  jet.style.cssText = `left:${vx.toFixed(1)}px; top:${(vy - 9).toFixed(1)}px; width:${len.toFixed(0)}px; height:18px; rotate:${ang.toFixed(1)}deg; --jet-ms:${jetMs}ms;`;
  arena.appendChild(jet);
  setTimeout(() => jet.remove(), jetMs + 300);
  await sleep(jetMs * 0.55);   // the cloud starts while the jet is still reaching

  const cloud = document.createElement('div');
  cloud.className = 'steamcloud';
  // The billow starts off toward the caster and settles over the warband, so
  // the gas visibly arrives FROM the machine instead of appearing on top of them.
  cloud.style.cssText = `left:${(cx - cw / 2).toFixed(0)}px; top:${(cy - ch / 2).toFixed(0)}px; width:${cw.toFixed(0)}px; height:${ch.toFixed(0)}px; --steam-ms:${ms}ms; --from-x:${vx < cx ? -34 : 34}%;`;
  arena.appendChild(cloud);
  setTimeout(() => cloud.remove(), ms + 400);

  // A puff over each fighter, so the bank has edges and the steam is visibly
  // ON them rather than behind them.
  boxes.forEach((b, i) => {
    const size = Math.max(70, (b.feet - b.top) * 0.95);
    const p = document.createElement('div');
    p.className = 'steampuff';
    p.style.cssText = `left:${(b.x - size / 2).toFixed(0)}px; top:${(b.feet - size * 0.85).toFixed(0)}px; width:${size.toFixed(0)}px; height:${size.toFixed(0)}px; --puff-ms:${beat(1400)}ms; --puff-delay:${beat(120 * i)}ms; --drift:${(i % 2 ? 10 : -10)}px;`;
    arena.appendChild(p);
    setTimeout(() => p.remove(), ms + 600);
  });
  // Hold on the cloud before the hits resolve, so the steam is visibly ON them
  // when the numbers come up rather than already thinning.
  await sleep(beat(420));
}

// Mortessa's Coffin: the coffin lifts off her back and sails to the ally, who vanishes inside as
// the lid comes down (the box itself is drawn by render once the Coffined status lands).
/* Ryuunosuke's Invulnerable Clone — the travel. The shadow leaves his shoulder, crosses the field
   and sets down on the FAR side of the mark, then cuts forward into its back and goes out.
   "Behind" is read off facing(u), so an enemy-side Ryuunosuke sends it the other way and it still
   arrives behind. It also arrives turned back toward the mark, which is why the drawing is flipped
   against his own facing rather than with it. */
const CLONE_FLIT_ART = `<svg viewBox="0 0 44 54" aria-hidden="true">
  <path d="M13 24 Q13 14 21 13 Q30 13.6 31.6 22 Q32.6 28 31.6 32 L15 33 Q13 29.6 13 24 Z" fill="#241e3a"/>
  <path d="M9.6 24.6 Q15 22 21.6 21.8 Q28.4 22 32.8 24.6 Q29.4 26.6 21.6 25.9 Q14 26.5 9.6 24.6 Z" fill="#2e2648"/>
  <path d="M20.6 13 L19 6 Q21.4 4.8 23.4 6.3 Z" fill="#241e3a"/>
  <path d="M11 36 Q21 31.6 31 36 Q33 43 32.2 50 L10 50.6 Q9 43 11 36 Z" fill="#241e3a"/>
  <path d="M33 38.5 L30.6 37 L43 18 Z" fill="#a6a6b4"/>
  <path d="M32.2 37.9 L41.8 19.6" stroke="#d6d6e2" stroke-width=".7" fill="none" opacity=".8"/>
  <path d="M34.4 39.2 L29.6 36.2" stroke="#4a4a56" stroke-width="2" stroke-linecap="round"/>
  <rect x="16.4" y="25.4" width="3.4" height="1.7" rx=".7" fill="#c04848"/>
  <rect x="22.4" y="25.2" width="4" height="1.8" rx=".7" fill="#c04848"/>
</svg>`;

const RYUU_SLASH_ANGLES = [-50, 50, -15, 15, -80];
function ryuuSlashMark(tg, dir) {
  const tb = stageBox(tg), ta = $('#arena');
  if (reduced || !tb || !ta) return;
  const ang = dir * pick(RYUU_SLASH_ANGLES);
  const slashW = tb.h * 1.4;
  const cx = tb.x, cy = tb.top + tb.h * 0.45;
  const s = document.createElement('div');
  s.className = 'clone-slash';
  s.style.cssText = `left:${(cx - slashW / 2).toFixed(0)}px; top:${cy.toFixed(0)}px; width:${slashW.toFixed(0)}px; transform:rotate(${ang}deg);`;
  ta.appendChild(s);
  s.animate([
    { opacity: 0, transform: `rotate(${ang}deg) scaleX(0.15)`, offset: 0 },
    { opacity: 1, transform: `rotate(${ang}deg) scaleX(1)`, offset: 0.12 },
    { opacity: 1, transform: `rotate(${ang}deg) scaleX(1)`, offset: 0.75 },
    { opacity: 0, transform: `rotate(${ang}deg) scaleX(1.05)`, offset: 1 },
  ], { duration: beat(900), easing: 'ease-out', fill: 'forwards' });
  setTimeout(() => s.remove(), beat(920));
}

async function cloneFlit(u, t) {
  const a = stageBox(u), b = stageBox(t), arena = $('#arena');
  if (reduced || !a || !b || !arena) { burst(t, 'smoke'); await sleep(reduced ? 0 : 160); return; }
  const d = facing(u);
  const el = document.createElement('div');
  el.className = 'cloneflit';
  const art = bodyEl(u)?.querySelector('.upic .art');
  if (art) el.appendChild(art.cloneNode(true));
  else el.innerHTML = CLONE_FLIT_ART;
  const clnEl = cloneArt(u);
  if (clnEl) clnEl.style.display = 'none';
  const w = a.w, h = a.h;
  // Appear directly behind the target — no travel
  const cx = b.x + d * b.w * 0.5;
  el.style.cssText = `left:${cx.toFixed(0)}px; top:${b.top.toFixed(0)}px; width:${w.toFixed(0)}px; height:${h.toFixed(0)}px; margin: 0 0 0 ${(-w / 2).toFixed(0)}px; transform:scaleX(${-d});`;
  arena.appendChild(el);
  // Snap in: fast fade-in
  el.animate([{ opacity: 0 }, { opacity: 0.85 }], { duration: beat(120), fill: 'forwards' });
  await wait(beat(100));
  // Hold while the slash plays (the caller draws the crescent), then fade out
  await wait(beat(500));
  el.animate([{ opacity: 0.85 }, { opacity: 0 }], { duration: beat(250), fill: 'forwards' });
  await wait(beat(260));
  el.remove();
}

/* The strike itself. The clone is not a unit, so there is no turn to give it: it is run here as a
   free blow credited to Ryuunosuke, the same way Mara's Covering Fire is. It is passed counter:true
   — not because it is a counter, but because that flag is what the engine reads for "this blow is
   not the attacker standing in front of you": it stops the mark riposting, snapping back or raising
   a guard against a shadow, and it slips past a bodyguard, which is what striking from behind means.
   Mark of Death overrides the random pick — a marked enemy is the only one it will go for. */
function cloneArt(u) { return bodyEl(u)?.querySelector('.upic .art > g[opacity=".72"]'); }

async function cloneStrike(u, sk) {
  if (!charNat(u).clone || u.hp <= 0 || sk.id === 'guard') return;
  const picks = validTargets(u, { target: 'enemy' });
  if (!picks.length) return;
  const marked = picks.filter((e) => has(e, 'deathmark'));
  const iaijutsu = !!u.iaijutsuTarget;
  const forced = iaijutsu ? picks.find(e => e.uid === u.iaijutsuTarget) : null;
  const tg = forced || pick(marked.length ? marked : picks);
  delete u.iaijutsuTarget;
  // A beat of delay so the player sees Ryuu's hit land before the clone steps in.
  await wait(beat(320));
  float(u, 'Clone', 'fx');
  log(`${u.name}'s shadow steps in behind ${tg.name}.`, u.side);
  markAttacked(tg);
  await cloneFlit(u, tg);
  ryuuSlashMark(tg, facing(u));
  burst(tg, 'blood');
  bump(tg, 'hurt');
  strikeOnce(u, tg, RYUU_CLONE_MULT * (iaijutsu ? 1.3 : 1), 'Invulnerable Clone', { counter: true });
  render();
  await wait(beat(350));
  const restored = cloneArt(u);
  if (restored) restored.style.display = '';
}

// Twin Slash: Ryuunosuke dashes from the front through the target and out behind them, while his
// clone dashes from behind through the target and out the front — they cross right on the enemy's
// body. Both cuts land as a red X that lingers. Guaranteed critical hit.
async function twinSlashSkill(u, t, sk) {
  const arena = $('#arena'), d = facing(u);
  const b = stageBox(t), me = stageBox(u);
  if (reduced || !b || !me || !arena) {
    // Fallback: just apply damage with no animation
    markAttacked(t);
    strikeOnce(u, t, sk.mult, sk.name, sk.o);
    strikeOnce(u, t, RYUU_CLONE_MULT, 'Twin Slash (Clone)', { counter: true, alwaysCrit: true });
    log(`${u.name} and his shadow slash through ${t.name} from both sides!`, u.side);
    render();
    applyHitEffects(u, t, sk.o || {});
    return;
  }
  const el = actorEl(u);
  // The front and back positions relative to the target
  const frontX = b.x - d * (b.w * 0.45 + me.w * 0.3);   // Ryuu's starting side
  const backX  = b.x + d * (b.w * 0.45 + me.w * 0.3);    // behind the target
  const footY  = b.feet + 2;
  // Hide the real clone art; we'll make a free-flying one
  const cln = cloneArt(u);
  if (cln) cln.style.display = 'none';
  // Build a clone element starting from behind the target
  const cel = document.createElement('div');
  cel.className = 'matrixclone';
  const art = bodyEl(u)?.querySelector('.upic .art');
  if (art) cel.appendChild(art.cloneNode(true));
  cel.style.cssText = `position:absolute; left:${backX.toFixed(0)}px; top:${b.top.toFixed(0)}px; width:${me.w.toFixed(0)}px; height:${me.h.toFixed(0)}px; margin:0 0 0 ${(-me.w / 2).toFixed(0)}px; z-index:200; transform:scaleX(${-d}); opacity:0;`;
  arena.appendChild(cel);
  // --- Phase 1: both dash to their starting positions ---
  // Ryuu dashes to the front of the target (normal dash)
  const trip = await dashTo(u, [t]);
  // Clone materializes behind the target
  cel.animate([{ opacity: 0 }, { opacity: 0.85 }], { duration: beat(200), fill: 'forwards' });
  await wait(180);
  // --- Phase 2: both slash THROUGH the target, crossing paths ---
  const crossMs = beat(280);
  // Ryuu: from front → through → behind. The dashTo left him held at trip.end; we continue from there.
  const [cx, cy] = dashXY(trip?.end || '0 0');
  const throughDx = d * (backX - frontX);   // how far across the target
  const passEnd = `${(cx + throughDx).toFixed(1)}px ${cy.toFixed(1)}px`;
  let crossAnim = null;
  if (el) {
    el.style.zIndex = 250;
    if (trip?.anim) trip.anim.cancel();
    if (el._dash) { el._dash.cancel(); el._dash = null; }
    crossAnim = el.animate([
      { translate: `${cx.toFixed(1)}px ${cy.toFixed(1)}px` },
      { translate: passEnd },
    ], { duration: crossMs, easing: 'ease-in-out', fill: 'forwards' });
  }
  // Clone: from behind → through → front (opposite direction)
  cel.animate([
    { left: `${backX.toFixed(0)}px` },
    { left: `${frontX.toFixed(0)}px` },
  ], { duration: crossMs, easing: 'ease-in-out', fill: 'forwards' });
  // Strike poses as they cross
  strikePose(u, true, sk);
  // Wait until they cross on the target (mid-point)
  await wait(crossMs * 0.45);
  // X slash marks on the target — the moment they cross
  const slashes = [];
  const slashW = b.w * 1.4;
  for (const angle of [-35, 35]) {
    const s = document.createElement('div');
    s.className = 'twin-x-slash';
    s.style.cssText = `left:${(b.x - slashW / 2).toFixed(0)}px; top:${(b.top + b.h * 0.45).toFixed(0)}px; width:${slashW.toFixed(0)}px; transform:rotate(${angle}deg);`;
    arena.appendChild(s);
    s.animate([
      { opacity: 0, transform: `rotate(${angle}deg) scaleX(0.15)`, offset: 0 },
      { opacity: 1, transform: `rotate(${angle}deg) scaleX(1)`, offset: 0.12 },
      { opacity: 1, transform: `rotate(${angle}deg) scaleX(1)`, offset: 0.8 },
      { opacity: 0, transform: `rotate(${angle}deg) scaleX(1.05)`, offset: 1 },
    ], { duration: beat(1400), easing: 'ease-out', fill: 'forwards' });
    slashes.push(s);
  }
  burst(t, 'blood');
  markAttacked(t);
  strikeOnce(u, t, sk.mult, sk.name, sk.o);
  strikeOnce(u, t, RYUU_CLONE_MULT, 'Twin Slash (Clone)', { counter: true, alwaysCrit: true });
  log(`${u.name} and his shadow slash through ${t.name} from both sides!`, u.side);
  render();
  // Wait for the rest of the crossing to finish
  if (crossAnim) await done(crossAnim, crossMs);   // done(): an undrawn page (app in the background) never finishes it
  await wait(beat(200));
  // --- Phase 3: both have passed through; hold a beat, then return ---
  // Clone fades out on the far side
  cel.animate([{ opacity: 0.85 }, { opacity: 0 }], { duration: beat(300), fill: 'forwards' });
  await wait(300);
  cel.remove();
  if (cln) cln.style.display = '';
  // Clean up slashes
  await wait(500);
  for (const s of slashes) s.remove();
  // Ryuu dashes back from behind the target to his home position
  if (el) {
    if (crossAnim) crossAnim.cancel();
    const ms = beat(300);
    const back = el.animate([{ translate: passEnd }, { translate: '0 0' }],
      { duration: ms, easing: 'ease-out' });
    el.style.zIndex = '';
    await done(back, ms);
  }
  applyHitEffects(u, t, sk.o || {});
  if (t.hp <= 0 && pv(u).killHeal && u.hp > 0) healUnit(u, u, Math.round(u.maxHp * pv(u).killHeal), 'Bloodlust');
  if (t.hp <= 0 && pv(u).killSpeed && u.hp > 0) { u.pos = Math.min(TRACK, (u.pos || 0) + pv(u).killSpeed); float(u, 'Shadow Step', 'fx'); }
  render();
}

// Shadow Matrix: 3-Rev channel. Rev 1 (cast): vanish in smoke. Rev 2: clones appear behind every
// enemy. Rev 3: all clones slash simultaneously, Ryuunosuke reappears.
function matrixVanish(u, on) {
  const el = actorEl(u);
  if (!el) return;
  if (on) el.setAttribute('data-matrix-vanished', '');
  else el.removeAttribute('data-matrix-vanished');
}

async function beginShadowMatrix(u, sk) {
  u.shadowMatrix = { revs: 2, sk };
  float(u, 'Shadow Matrix', 'fx');
  log(`${u.name} vanishes into the shadows — replicas will appear behind every enemy.`, u.side);
  burst(u, 'smoke');
  matrixVanish(u, true);
  const cln = cloneArt(u);
  if (cln) cln.style.display = 'none';
  render();
  await wait(600);
}

async function matrixClonesAppear(u) {
  const foes = foesOf(u).filter((f) => f.hp > 0 && !outOfReach(f));
  if (!foes.length) return;
  const arena = $('#arena');
  if (!arena) return;
  const art = bodyEl(u)?.querySelector('.upic .art');
  u.shadowMatrix.cloneEls = [];
  for (const f of foes) {
    const b = stageBox(f);
    if (!b) continue;
    const d = facing(u);
    const el = document.createElement('div');
    el.className = 'matrixclone';
    if (art) {
      const copy = art.cloneNode(true);
      const cln = copy.querySelector('g[opacity=".72"]');
      if (cln) cln.remove();
      el.appendChild(copy);
    } else el.innerHTML = CLONE_FLIT_ART;
    el.dataset.d = d;
    el.style.cssText = `position:absolute; left:${(b.x + d * b.w * 0.5).toFixed(0)}px; top:${b.top.toFixed(0)}px; width:${b.w.toFixed(0)}px; height:${b.h.toFixed(0)}px; margin:0 0 0 ${(-b.w / 2).toFixed(0)}px; opacity:0; transform:scaleX(${-d}); pointer-events:none; z-index:5;`;
    arena.appendChild(el);
    el.animate([
      { opacity: 0, transform: `scaleX(${-d}) scale(0.7)` },
      { opacity: 0.8, transform: `scaleX(${-d}) scale(1)` }
    ], { duration: 350, fill: 'forwards', easing: 'ease-out' });
    burst(f, 'smoke');
    u.shadowMatrix.cloneEls.push(el);
  }
  float(u, 'Replicas', 'fx');
  log(`Shadow replicas materialise behind every enemy.`, u.side);
  render();
  matrixVanish(u, true);
  await wait(450);
}

async function matrixResolve(u) {
  const { sk, cloneEls } = u.shadowMatrix;
  const foes = foesOf(u).filter((f) => f.hp > 0 && !outOfReach(f));
  if (cloneEls) {
    for (const cel of cloneEls) {
      cel.getAnimations().forEach((a) => a.cancel());
      const d = +(cel.dataset.d || 1);
      const face = `scaleX(${-d})`;
      const dash = cel.offsetWidth * 1.4;
      cel.animate([
        { transform: `translateX(${(d * 8).toFixed(0)}px) ${face}`, opacity: 0.85 },
        { transform: `translateX(${(-d * dash * 0.1).toFixed(0)}px) ${face}`, opacity: 1, offset: 0.12 },
        { transform: `translateX(${(-d * dash).toFixed(0)}px) ${face}`, opacity: 0.5, offset: 0.55 },
        { transform: `translateX(${(-d * dash * 1.2).toFixed(0)}px) ${face}`, opacity: 0 },
      ], { duration: beat(420), easing: 'cubic-bezier(.15,.85,.25,1)', fill: 'forwards' });
    }
  }
  const arena = $('#arena');
  const slashes = [];
  for (const f of foes) {
    const b = stageBox(f);
    if (!b || !arena) continue;
    const slashW = b.w * 1.3;
    const s = document.createElement('div');
    s.className = 'matrix-slash';
    s.style.cssText = `left:${(b.x - slashW / 2).toFixed(0)}px; top:${(b.top + b.h * 0.45).toFixed(0)}px; width:${slashW.toFixed(0)}px;`;
    arena.appendChild(s);
    s.animate([
      { opacity: 0, transform: 'scaleX(0.2)', offset: 0 },
      { opacity: 1, transform: 'scaleX(1)', offset: 0.1 },
      { opacity: 1, transform: 'scaleX(1)', offset: 0.8 },
      { opacity: 0, transform: 'scaleX(1.05)', offset: 1 },
    ], { duration: beat(1400), easing: 'ease-out', fill: 'forwards' });
    slashes.push(s);
  }
  await wait(180);
  for (const f of foes) {
    strikeOnce(u, f, sk.mult, sk.name, { counter: true, noDodge: true });
  }
  log(`${u.name}'s shadow replicas slash every enemy at once!`, u.side);
  render();
  await wait(1200);
  for (const s of slashes) s.remove();
  if (cloneEls) for (const cel of cloneEls) cel.remove();
  u.shadowMatrix = null;
  matrixVanish(u, false);
  const cln = cloneArt(u);
  if (cln) cln.style.display = '';
  burst(u, 'smoke');
  float(u, 'Returns', 'fx');
  log(`${u.name} steps back out of the shadows.`, u.side);
  render();
  await wait(400);
}

async function coffinFly(u, t) {
  await castPose(u, true);
  const a = stageBox(u), b = stageBox(t), arena = $('#arena');
  if (reduced || !a || !b || !arena) { burst(t, 'grave'); await sleep(reduced ? 0 : 200); return; }
  const el = document.createElement('div');
  el.className = 'coffinfly';
  el.textContent = '⚰️';
  el.style.cssText = `left:${a.x.toFixed(0)}px; top:${(a.top + 6).toFixed(0)}px;`;
  arena.appendChild(el);
  const dx = b.x - a.x, dy = (b.top + b.h * 0.4) - (a.top + 6), ms = beat(460);
  const anim = el.animate([
    { transform: 'translate(-50%,-50%) rotate(-8deg) scale(.9)' },
    { transform: `translate(calc(-50% + ${(dx * 0.5).toFixed(0)}px), calc(-50% + ${(dy * 0.5 - 26).toFixed(0)}px)) rotate(6deg) scale(1.06)`, offset: 0.55 },
    { transform: `translate(calc(-50% + ${dx.toFixed(0)}px), calc(-50% + ${dy.toFixed(0)}px)) rotate(0deg) scale(1)` },
  ], { duration: ms, easing: 'cubic-bezier(.4,.9,.3,1)' });
  await (anim.finished ? done(anim, ms) : sleep(ms));   // done(): an undrawn page (app in the background) never finishes it
  burst(t, 'grave');
  el.remove();
}

// Tharos's Riptide / Undertow: a blue wave rolls across the targets (the knockback itself is in the
// skill's o.knockback). Fire-and-forget — the overlay removes itself; each target gets a splash.
function waterSweep(u, targets) {
  const arena = $('#arena'), boxes = targets.map(stageBox).filter(Boolean);
  if (reduced || !arena || !boxes.length) return;
  const left = Math.min(...boxes.map((b) => b.x)), right = Math.max(...boxes.map((b) => b.x));
  const top = Math.min(...boxes.map((b) => b.top)), bot = Math.max(...boxes.map((b) => b.feet));
  const w = Math.max(170, right - left + 240);
  const h = Math.max(74, Math.round((bot - top) * 0.62) + 26);   // chest-high, not head-high
  const ms = beat(820);
  const el = document.createElement('div');
  el.className = 'watersweep';
  // Seated on the ground line the targets stand on, so the water rolls along the floor.
  el.style.cssText = `left:${(left - 120).toFixed(0)}px; top:${(bot - h + 10).toFixed(0)}px; width:${w.toFixed(0)}px; height:${h.toFixed(0)}px; --sweep-ms:${ms}ms; --sweep-dir:${facing(u)};`;
  arena.appendChild(el);
  el.addEventListener('animationend', (e) => { if (!e.pseudoElement) el.remove(); });
  setTimeout(() => el.remove(), ms + 400);
  for (const t of targets) if (stageBox(t)) burst(t, 'splash');
}

// Trident Lunge: Tharos springs up and forward, hanging a beat at the top, then comes down overhead.
async function leapPose(u) {
  const d = facing(u);
  if (!pose(u, [{ transform: 'none' },
    { transform: `translate(${d * 24}px, -50px) rotate(${d * 7}deg)`, offset: 0.4 },
    { transform: `translate(${d * 40}px, -34px) rotate(${d * 12}deg)`, offset: 0.62 },
    { transform: `translate(${d * 44}px, 2px) rotate(${d * 16}deg)`, offset: 0.8 },
    { transform: 'none' }], 520)) return;
  await sleep(beat(340));
}

/* Thurgan's Deadfall: he lifts the target on a well of gravity (the target bobs up, hangs, then
   crashes down) while Thurgan himself drives his fist into the floor. The hit resolves on impact. */
/* Three coils round the chest and a tail whipping off the top one. Drawn as
   flat ellipses rather than a wrapped helix: at 68x84 on a body that is about
   to be swung through the air, a true helix reads as scribble, while three bands
   read as a rope at a glance — which is all the half second it is on screen
   allows. Each coil is stroked three times (glow, cord, running highlight). */
const ROPE_COILS = [
  { cx: 34, cy: 30, rx: 21, ry: 5.5 },
  { cx: 34, cy: 41, rx: 23, ry: 6 },
  { cx: 34, cy: 52, rx: 20, ry: 5.5 },
];
const ROPE_SVG = `<svg viewBox="0 0 68 84" aria-hidden="true">${
  ['rb-glow', 'rb-body', 'rb-hi'].map((cls) =>
    ROPE_COILS.map((c) => `<ellipse class="${cls}" cx="${c.cx}" cy="${c.cy}" rx="${c.rx}" ry="${c.ry}"/>`).join('') +
    `<path class="${cls}" d="M13 28 Q4 20 7 10"/>`).join('')
}</svg>`;

/* Bind the target. Returns the cord so the caller can snap it off on impact;
   null when the body is gone, which the caller treats as "no rope to cut". */
function ropeBind(t) {
  const b = bodyEl(t);
  if (!b) return null;
  const el = document.createElement('div');
  el.className = 'ropebind';
  el.innerHTML = ROPE_SVG;
  b.appendChild(el);
  return el;
}
function ropeSnap(el) {
  if (!el) return;
  el.classList.add('snap');
  setTimeout(() => el.remove(), 260);
}

/* How far to throw a body so the arena's top edge swallows it and only the
   boots are left hanging in view. Measured, not a constant: the arena is a
   different height on a phone held sideways than on a desktop, and the body
   scales with --size, so any fixed pixel figure is right on exactly one
   screen. #arena clips its overflow, which is what does the cutting.

   SHOW is the slice left below the edge. The floor keeps the throw readable
   if the measurement ever comes back nonsense (a hidden arena measures zero),
   and the ceiling stops a very tall arena turning the lift into a long wait
   for a body to come back down. */
function liftClearance(t) {
  const b = bodyEl(t), arena = $('#arena');
  const SHOW = 0.22, MIN = 70, MAX = 420;
  if (!b || !arena) return 150;
  const bb = b.getBoundingClientRect(), ab = arena.getBoundingClientRect();
  if (!bb.height || !ab.height) return 150;
  return Math.round(Math.min(MAX, Math.max(MIN, bb.bottom - ab.top - bb.height * SHOW)));
}

/* The lift-and-drop. With `rope`, Zul'kan's Ground Slam shape: he is already
   in front of the target (every melee skill dashes there before this runs),
   the cord cinches on, the body goes up on it, and he hauls it back down.
   The rope lets go on the landing, not before — a cord that vanishes at the
   top of the arc makes the drop look like the target simply fell. */
async function deadfallLift(u, t, o = {}) {
  const d = facing(u);
  let rope = null;
  if (o.rope) {
    rope = ropeBind(t);
    await sleep(beat(220));           // let it cinch before anything moves
  }
  /* One clock for the throw, so the two bodies and the impact cannot drift
     apart. The shape is up / HANG / down: the hang is the point — a body
     yanked off its feet and held there reads as someone else's doing, where
     a straight up-and-down reads as a stumble. The drop is the shortest leg
     of the three and runs on an ease-in, so it arrives hard after the wait. */
  const MS = 1250, UP = 0.18, APEX = 0.28, FALL = 0.62, LAND = 0.78;
  pose(u, [{ transform: 'none' },
    { transform: `translateY(-8px) scaleY(1.06) rotate(${-d * 5}deg)`, offset: UP },
    { transform: `translateY(-10px) scaleY(1.08) rotate(${-d * 7}deg)`, offset: APEX },
    { transform: `translateY(-9px) scaleY(1.07) rotate(${-d * 6}deg)`, offset: FALL },   // holding them up
    { transform: `translateY(6px) scaleY(.88) rotate(${d * 12}deg)`, offset: LAND, easing: 'cubic-bezier(.6,0,1,.4)' },
    { transform: `translateY(3px) scaleY(.94) rotate(${d * 7}deg)`, offset: 0.88 },
    { transform: 'none' }], MS);
  burst(t, 'gravity');
  const rise = liftClearance(t);
  if (!pose(t, [{ transform: 'none' },
    { transform: `translateY(${-rise}px) scale(.92)`, offset: UP, easing: 'ease-out' },
    { transform: `translateY(${-rise - 8}px) scale(.9)`, offset: APEX },
    { transform: `translateY(${-rise - 4}px) scale(.9)`, offset: FALL, easing: 'cubic-bezier(.5,0,1,.45)' },  // hangs, then drops
    { transform: 'translateY(8px) scale(1.08)', offset: LAND },
    { transform: 'translateY(4px) scale(1.04)', offset: 0.88 },
    { transform: 'none' }], MS)) { ropeSnap(rope); return; }
  await sleep(beat(MS * LAND));
  tremorFx(500);
  burst(t, 'smoke');
  ropeSnap(rope);                     // it lets go as they land
  await sleep(beat(140));
}

/* Thurgan's Event Horizon: a gravity vortex yanks the target — a brief purple inward spiral. */
function gravPullFx(t) {
  const b = bodyEl(t);
  if (reduced || !b) return;
  const el = document.createElement('div');
  el.className = 'burst burst-gravity';
  el.style.cssText = 'animation: ring .5s ease-in reverse; border-width: 3px;';
  b.appendChild(el);
  setTimeout(() => el.remove(), 600);
}

const LODGE_SWORD_SVG = `<svg viewBox="0 0 60 10" width="60" height="10" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="lsB" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#eafff2"/><stop offset=".5" stop-color="#6ef0a8"/><stop offset="1" stop-color="#1f9e62"/></linearGradient></defs><path d="M10 3 L56 3 L60 5 L56 7 L10 7 Z" fill="url(#lsB)" stroke="#167a4c" stroke-width=".5"/><path d="M12 4.8 L56 4.8" stroke="#f2fff8" stroke-width=".5" stroke-linecap="round"/><rect x="7" y="1" width="4" height="8" rx=".8" fill="url(#lsB)" stroke="#167a4c" stroke-width=".5"/><rect x="2" y="3" width="6" height="4" rx=".7" fill="#6ef0a8" stroke="#167a4c" stroke-width=".5"/><circle cx="1.5" cy="5" r="1.5" fill="#6ef0a8"/></svg>`;

/* Where each stuck blade sits, in the order they land: every one gets its own height, its own depth
   and its own tilt, so five blades in a body read as five. Counted from the blades already drawn on the
   body (not from t.lodged, which a volley bumps all at once - that stacked them in one spot). */
const LODGE_SPOTS = [[46, 10, 0], [58, 14, -7], [34, 6, 6], [66, 4, -12], [40, 18, 10],
                     [52, 2, -4], [28, 14, 12], [62, 20, -9], [44, 0, 7], [36, 22, -6]];

function lodgeSwordFx(t) {
  const b = bodyEl(t);
  if (reduced || !b) return;
  const swordUser = [...state.teams.p, ...state.teams.e].find(a => a.maxSwords && a.hp > 0);
  const vEl = swordUser ? bodyEl(swordUser) : null;
  const tr = b.getBoundingClientRect(), vr = vEl ? vEl.getBoundingClientRect() : tr;
  const dx = (tr.left + tr.width / 2) - (vr.left + vr.width / 2);
  const dy = (tr.top + tr.height / 2) - (vr.top + vr.height / 2);
  const ang = Math.atan2(dy, dx) * 180 / Math.PI;
  const n = b.querySelectorAll('.lodged-sword').length;
  const [bot, left, tilt] = LODGE_SPOTS[n % LODGE_SPOTS.length];
  const rot = ang + tilt;
  const el = document.createElement('div');
  el.className = 'lodged-sword';
  el.innerHTML = LODGE_SWORD_SVG;
  el.style.cssText = `position:absolute; bottom:${bot}%; left:${left}%; opacity:0; transform:rotate(${rot}deg); filter:drop-shadow(0 0 4px #6ef0a8); pointer-events:none; z-index:10;`;
  b.appendChild(el);
  el.animate([
    { opacity: 0, transform: `rotate(${rot}deg) translateX(-20px)` },
    { opacity: 1, transform: `rotate(${rot}deg) translateX(0)` }
  ], { duration: 300, fill: 'forwards' });
}

function returnSwordFx(v, swordOwner) {
  const vEl = bodyEl(v), hEl = bodyEl(swordOwner);
  if (reduced || !vEl || !hEl) { clearLodgedSwords(v); return; }
  const swords = vEl.querySelectorAll('.lodged-sword');
  const vr = vEl.getBoundingClientRect(), hr = hEl.getBoundingClientRect();
  const dx = hr.left + hr.width / 2 - (vr.left + vr.width / 2), dy = hr.top + hr.height / 2 - (vr.top + vr.height / 2);
  swords.forEach((s, i) => {
    // They do not snap home: each one works free, rises, and drifts back to him on the air.
    const ms = beat(1500), lag = beat(220) * i;
    s.animate([
      { transform: 'translateX(0)', opacity: 1 },
      { transform: 'translate(0px, -10px)', opacity: 1, offset: .15 },
      { transform: `translate(${dx * .5}px, ${dy * .5 - 34}px) scale(.85)`, opacity: .95, offset: .55 },
      { transform: `translate(${dx}px, ${dy - 8}px) scale(.75)`, opacity: .85, offset: .9 },
      { transform: `translate(${dx}px, ${dy}px) scale(.7)`, opacity: 0 }
    ], { duration: ms, delay: lag, easing: 'ease-in-out', fill: 'forwards' });
    setTimeout(() => s.remove(), ms + lag + 60);
  });
}

async function returnSwordsFx(u) {
  const all = [...state.teams.p, ...state.teams.e].filter((f) => f.lodged && f.side !== u.side);
  for (const f of all) returnSwordFx(f, u);
  if (all.length) await sleep(beat(1500));   // let them float all the way home before he moves on
  clearLodgedSwords();
}

function clearLodgedSwords(v) {
  const scope = v ? bodyEl(v) : document;
  if (scope) scope.querySelectorAll('.lodged-sword').forEach((e) => e.remove());
}

/* Riptide: Tharos plants his feet and hauls the trident overhead, holding it up while the water
   answers him. He never leaves his place - the wave does the traveling. */
async function tridentRaise(u) {
  const d = facing(u);
  if (!pose(u, [{ transform: 'none' },
    { transform: `translateY(-7px) scaleY(1.06) rotate(${-d * 6}deg)`, offset: 0.34, easing: 'ease-out' },
    { transform: `translateY(-10px) scaleY(1.08) rotate(${-d * 8}deg)`, offset: 0.58 },
    { transform: `translateY(-4px) scaleY(1.03) rotate(${-d * 3}deg)`, offset: 0.82 },
    { transform: 'none' }], 640)) return;
  await sleep(beat(430));
}

/* Undertow: he hoists the trident high and drives it butt-first into the floor. The ground answers
   with a shudder and the water comes up out of it. */
async function tridentSlam(u) {
  const d = facing(u);
  const ok = pose(u, [{ transform: 'none' },
    { transform: `translateY(-12px) scaleY(1.09) rotate(${-d * 9}deg)`, offset: 0.32, easing: 'ease-out' },
    { transform: `translateY(-13px) scaleY(1.09) rotate(${-d * 10}deg)`, offset: 0.44 },
    { transform: `translateY(6px) scaleY(.9) rotate(${d * 6}deg)`, offset: 0.6, easing: 'cubic-bezier(.6,0,1,.4)' },
    { transform: `translateY(3px) scaleY(.96) rotate(${d * 3}deg)`, offset: 0.74 },
    { transform: 'none' }], 780);
  if (!ok) return;
  await sleep(beat(468));   // the shudder lands with the trident, not with the wind-up
  tremorFx(700);
  burst(u, 'splash');
  await sleep(beat(170));
}

// The floor shudders: the cave-quake judder, reused by anything that drives into the ground.
function tremorFx(ms = 900) {
  const arena = $('#arena');
  if (reduced || !arena) return;
  arena.classList.remove('tremor');
  void arena.offsetWidth;   // restart the shake if two pounds land back to back
  arena.classList.add('tremor');
  setTimeout(() => arena.classList.remove('tremor'), ms);
}

// One short tremor: the cave-quake judder and grit for two beats, and dust at every enemy's feet.
function quakeFx(targets) {
  tremorFx(900);
  for (const t of targets) if (t.hp > 0) burst(t, 'smoke');
}

// A great crescent carved across the struck target, mirrored to come from the attacker's side.
function slashFx(t, dir) {
  const b = bodyEl(t);
  if (reduced || !b || t.hp <= 0) return;
  const el = document.createElement('div');
  el.className = `slashArc${dir < 0 ? ' flip' : ''}`;
  el.innerHTML = '<svg viewBox="0 0 100 100"><path d="M74 4 A76 76 0 0 0 74 96 A46 46 0 0 1 74 4 Z"/></svg>';
  b.appendChild(el);
  el.addEventListener('animationend', () => el.remove(), { once: true });
  setTimeout(() => el.remove(), 800);
}

/* Where a champion's gun barrel is at the moment the shot leaves it (on their attack clip), as a
   share of the body box: [ahead of centre toward the target, down from the top]. Every shot they
   fire starts there, with fire and smoke at the muzzle (muzzleFlash). */
const MUZZLE = { mara: [0.295, 0.317] };

/* Ricochet: the round skips off its first mark in a spray of sparks, thrown out along its new line. */
function ricochetSpark(at, ang) {
  if (reduced) return;
  const el = document.createElement('div');
  el.className = 'ricospark';
  Object.assign(el.style, { left: `${at.x}px`, top: `${at.y}px`, transform: `rotate(${ang}rad)` });
  // sparks fanned around the outgoing direction (0 rad = along it), plus a white flash at the point
  el.innerHTML = `<svg viewBox="-20 -20 40 40" aria-hidden="true"><circle r="4" fill="#fff" opacity=".95"/>`
    + [-0.9, -0.45, -0.15, 0.2, 0.5, 0.95].map((a, i) => {
      const r0 = 3, r1 = 9 + (i % 3) * 3;
      return `<line x1="${(r0 * Math.cos(a)).toFixed(1)}" y1="${(r0 * Math.sin(a)).toFixed(1)}" x2="${(r1 * Math.cos(a)).toFixed(1)}" y2="${(r1 * Math.sin(a)).toFixed(1)}" stroke="${i % 2 ? '#ffe9a8' : '#ffffff'}" stroke-width="1.4" stroke-linecap="round"/>`;
    }).join('') + '</svg>';
  $('#arena').appendChild(el);
  const ms = beat(280);
  done(el.firstElementChild.animate([{ transform: 'scale(.3)', opacity: 1 }, { transform: 'scale(1.25)', opacity: 0 }],
    { duration: ms, easing: 'ease-out', fill: 'forwards' }), ms).then(() => el.remove());
}

function muzzleFlash(at, d) {
  if (reduced) return;
  const arena = $('#arena');
  const fire = document.createElement('div');
  fire.className = 'muzzle-fire';
  Object.assign(fire.style, { left: `${at.x}px`, top: `${at.y}px`, transform: `scaleX(${d})` });
  fire.innerHTML = `<svg viewBox="0 0 34 22" aria-hidden="true">
    <path d="M0 11 Q9 1 21 5 Q29 7 34 11 Q29 15 21 17 Q9 21 0 11 Z" fill="#ff7a22"/>
    <path d="M0 11 Q7 5 16 7.5 Q22 9.5 25 11 Q22 12.5 16 14.5 Q7 17 0 11 Z" fill="#ffc24a"/>
    <ellipse cx="5" cy="11" rx="6" ry="4.2" fill="#fff4cf"/></svg>`;
  arena.appendChild(fire);
  const ms = beat(260);
  done(fire.firstElementChild.animate([{ transform: 'scale(.25)', opacity: 1 }, { transform: 'scale(1.15)', opacity: 1, offset: 0.3 },
    { transform: 'scale(.85)', opacity: 0 }], { duration: ms, easing: 'ease-out', fill: 'forwards' }), ms).then(() => fire.remove());
  // Powder smoke: a few puffs that roll out ahead of the barrel, swell, climb and thin away.
  for (let i = 0; i < 4; i++) {
    const puff = document.createElement('div');
    puff.className = 'muzzle-smoke';
    Object.assign(puff.style, { left: `${at.x + d * (4 + i * 3)}px`, top: `${at.y + (i % 2 ? 2 : -2)}px` });
    arena.appendChild(puff);
    const life = beat(1000 + i * 180);
    done(puff.animate([{ transform: 'translate(0, 0) scale(.35)', opacity: 0.9 },
      { transform: `translate(${d * (14 + i * 9)}px, ${-(8 + i * 7)}px) scale(${1.5 + i * 0.35})`, opacity: 0 }],
      { duration: life, delay: beat(30 + i * 45), easing: 'ease-out', fill: 'both' }), life + beat(30 + i * 45)).then(() => puff.remove());
  }
}

// How close to the top of the arena a lobbed shot is allowed to peak before the clip would bite.
// A few pixels, so the art's own height doesn't clip the crown of the arc (see the lift note below).
const ARC_CEILING_MARGIN = 14;

// p.bounceFrom (a unit): the round is already in flight - it glances off that unit, where the last
// shot struck, and carries on to t (Ricochet). No muzzle, no second shot: a spark where it bounced.
async function shoot(u, t, p, spread) {
  // p.toPoint: a shot at a spot on the field rather than a body (Emptied Hands at where its mark stood).
  const s = stageBox(p.bounceFrom || u), e = p.toPoint ? { x: p.toPoint.x, top: p.toPoint.y, h: 0, w: 0, feet: p.toPoint.y } : stageBox(t);
  if (reduced || !s || !e) return;
  if (p.swordThrow) actorEl(u)?.classList.add('sword-thrown');
  const d = facing(u);
  const mz = !p.bounceFrom && !p.from && MUZZLE[u.id];
  // p.from: a shot that leaves from a set point on the field (a blade in Riven's fan), not from the shooter.
  const from = p.from ? { ...p.from } : p.bounceFrom ? { x: s.x, y: s.top + s.h * 0.45 }
    : mz ? { x: s.x + d * s.w * mz[0], y: s.top + s.h * mz[1] } : { x: s.x + d * s.w * 0.3, y: s.top + s.h * 0.45 };
  if (spread) { from.y += spread; }
  if (mz) muzzleFlash(from, d);
  if (p.bounceFrom) ricochetSpark(from, Math.atan2(e.top + e.h * 0.45 - from.y, e.x - from.x));
  const to = { x: e.x, y: e.top + e.h * 0.45 + (spread || 0) };
  if (p.endAt) Object.assign(to, p.endAt(e, to, from));   // the round stops short of them, or flies on past
  if (p.kind === 'bolt') return zap(from, to);
  const el = document.createElement('div');
  el.className = `proj proj-${p.kind}`;
  if (p.color) el.style.setProperty('--c', p.color);
  const art = PROJ_ART[p.kind];
  if (art) {
    const [w, h, svg] = art;
    Object.assign(el.style, { width: `${w}px`, height: `${h}px`, margin: `${-h / 2}px 0 0 ${-w / 2}px` });
    el.innerHTML = `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true">${svg}</svg>`;
  }
  $('#arena').appendChild(el);
  // Flight time grows with distance; lobbed shots (pots, shells) hang a little longer in the air,
  // and a wandering wisp takes its time getting there.
  const dist = Math.hypot(to.x - from.x, to.y - from.y);
  /* HOW HIGH A LOB IS ALLOWED TO GO. A quadratic peaks at HALF its control offset, and .arena clips
     at its top edge (overflow: hidden), so a shot is decapitated once lift/2 climbs past the muzzle's
     distance from that edge — i.e. the real ceiling is twice that distance. That distance is not a
     constant: it falls out of the arena's rendered height AND which slot the shooter stands in (a
     back-row champion sits roughly half as far below the top as a front-row one), so any single
     hardcoded lift has to be timid enough for the worst case and every other shot pays for it.
     So p.lift is a REQUEST, not a promise: ask for the arc you want and take whatever the field can
     actually give, less a small margin. A tall arena shows the full arc, a short one shows the
     highest arc that still fits, and neither loses the skull off the top of the screen.
     Worked out here rather than down in the arc branch because the hang time below needs to know
     the arc that will ACTUALLY be flown, not the one that was asked for. */
  const headroom = Math.min(from.y, to.y) - ARC_CEILING_MARGIN;
  const lift = p.arc ? Math.min(p.lift || 140, Math.max(0, headroom * 2)) : 0;
  /* HANG TIME. Square root because a thrown thing's flight time goes with the square root of how
     high it was thrown. Give a tall lob the same 500ms as a shallow one and it has to climb faster
     to get there in time, which reads as a flat, snappy line drive — exactly the opposite of the
     heavy overhand throw a high arc is supposed to sell. Scaled off the 140 default, so an ordinary
     pot is unchanged and only the genuinely high shots linger.
     Floored at the 1.25 every lobbed shot used to get, so this can only ever ADD hang: a modest lob
     like the plain sling prices out below 1.25 on the curve alone and would otherwise have come out
     of this change flying faster than it did before. */
  const arcHang = p.lift ? clamp(Math.sqrt(lift / 140), 1.25, 2.2) : 1;
  const ms = beat(p.wander ? clamp(dist * 1.1, 520, 860) : p.arc ? clamp(dist * 0.6, 240, 400) * arcHang : clamp(dist * 0.4, 120, 260));
  const deg = (dx, dy) => Math.atan2(dy, dx) * 180 / Math.PI;
  const ang = p.upright ? 0 : deg(to.x - from.x, to.y - from.y);
  const at = (x, y, r) => `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) rotate(${r.toFixed(1)}deg)`;
  let frames;
  if (p.arc) {
    // Lobbed: a smooth parabola (peaking at lift / 2 above the higher end — lift is clamped to the
    // field's headroom up above), sampled into keyframes. arc: true tumbles end over end;
    // arc: 'curve' flies nose-first along the curve.
    const c = { x: (from.x + to.x) / 2, y: Math.min(from.y, to.y) - lift };
    let prev = null;
    frames = Array.from({ length: 13 }, (_, i) => {
      const k = i / 12, j = 1 - k;
      const x = j * j * from.x + 2 * j * k * c.x + k * k * to.x, y = j * j * from.y + 2 * j * k * c.y + k * k * to.y;
      let r = p.upright ? 0 : p.arc === 'curve' ? deg(j * (c.x - from.x) + k * (to.x - c.x), j * (c.y - from.y) + k * (to.y - c.y)) : facing(u) * 360 * k;
      if (prev != null && p.arc === 'curve') r += 360 * Math.round((prev - r) / 360);   // no spinning the long way round
      prev = r;
      return { transform: at(x, y, r) };
    });
  } else if (p.wander) {
    // Wandering (Cadris's grave-firefly): weaves on a random path, loops and doubles back, and only
    // homes in on the target at the very end. The wobble fades to nothing at both ends (sin πk), so it
    // still leaves the hand and lands on the target exactly. Faces the way it's drifting.
    const dx = to.x - from.x, dy = to.y - from.y, len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len, ny = dx / len, amp = clamp(len * 0.35, 30, 90);
    const [s0, s1, s2] = [0, 1, 2].map(() => Math.random() * Math.PI * 2);
    const pt = (k) => {
      const env = Math.sin(Math.PI * k);
      const side = amp * env * (0.65 * Math.sin(2 * Math.PI * 1.5 * k + s0) + 0.35 * Math.sin(2 * Math.PI * 3 * k + s1));
      const along = amp * 0.3 * env * Math.sin(2 * Math.PI * 2 * k + s2);
      return { x: from.x + dx * k + nx * side + (dx / len) * along, y: from.y + dy * k + ny * side + (dy / len) * along };
    };
    const n = 28;
    frames = Array.from({ length: n + 1 }, (_, i) => {
      const a = pt(i / n), b = pt(Math.min(1, (i + 1) / n)), z = pt(Math.max(0, (i - 1) / n));
      return { transform: at(a.x, a.y, deg(b.x - z.x, b.y - z.y)) };
    });
  } else frames = [{ transform: at(from.x, from.y, ang) }, { transform: at(to.x, to.y, ang) }];
  const anim = el.animate(frames, { duration: ms, easing: p.arc ? 'ease-in-out' : 'linear' });
  await done(anim, ms);
  el.remove();
  const impact = p.impact || ((p.kind === 'fire' || p.kind === 'shell') ? 'fire' : null);
  if (impact === 'boom') { burst(t, 'fire'); burst(t, 'smoke'); } else if (impact) burst(t, impact);
  if (p.swordThrow) actorEl(u)?.classList.remove('sword-thrown');
}

// Lightning: a jagged bolt that flickers between attacker and target.
async function zap(from, to) {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'bolt');
  const pts = [[from.x, from.y]];
  for (let i = 1; i < 6; i++) {
    const k = i / 6;
    pts.push([from.x + (to.x - from.x) * k + (Math.random() - 0.5) * 18, from.y + (to.y - from.y) * k + (Math.random() - 0.5) * 28]);
  }
  pts.push([to.x, to.y]);
  svg.innerHTML = `<polyline points="${pts.map((p) => p.map((n) => n.toFixed(1)).join(',')).join(' ')}"/>`;
  $('#arena').appendChild(svg);
  const anim = svg.animate([{ opacity: 0 }, { opacity: 1, offset: 0.2 }, { opacity: 0.5, offset: 0.5 }, { opacity: 1, offset: 0.7 }, { opacity: 0 }], { duration: beat(300) });
  await done(anim, beat(300));
  svg.remove();
}

/* THE STORM CAIRN'S SHOCK (totemPulse). Thrown from the stone's crown — the lightning carved on top of
   it (totemStorm), not its middle — at the enemy the cairn marked. Three strikes down the same gap, each
   along a freshly jagged path, because lightning never takes one twice and a bolt redrawn identically
   reads as a static picture being blinked on and off. */
const CAIRN_STRIKES = 3;
const CAIRN_CROWN = 0.16;   // how far down the stone the lit crown sits, as a share of its height

/* A jagged run between two fixed points. The wander is ACROSS the line of flight and pinched to nothing
   at both ends, so the bolt bows out between crown and body instead of fraying off either one. */
function stormPath(from, to, jag) {
  const steps = 9, dx = to.x - from.x, dy = to.y - from.y;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const pts = [[from.x, from.y]];
  for (let i = 1; i < steps; i++) {
    const k = i / steps;
    const off = (Math.random() - 0.5) * jag * Math.sin(k * Math.PI);
    pts.push([from.x + dx * k + nx * off, from.y + dy * k + ny * off]);
  }
  pts.push([to.x, to.y]);
  return pts;
}

const ptsAttr = (pts) => pts.map((p) => p.map((n) => n.toFixed(1)).join(',')).join(' ');

// A branch that forks off the main line partway along and dies in the air short of anything.
function stormFork(pts, side) {
  const i = 2 + Math.floor(Math.random() * Math.max(1, pts.length - 4));
  const [x, y] = pts[i], [px, py] = pts[i - 1];
  const a = Math.atan2(y - py, x - px) + side * (0.5 + Math.random() * 0.5);
  const run = 26 + Math.random() * 30;
  const out = [[x, y]];
  for (let j = 1; j <= 3; j++) {
    const k = j / 3;
    out.push([x + Math.cos(a) * run * k + (Math.random() - 0.5) * 10, y + Math.sin(a) * run * k + (Math.random() - 0.5) * 10]);
  }
  return out;
}

// The arena lit from where the bolt came down, and a kick under it. One per shock, on the strike
// that carries the hurt — see the note in cairnBolt about why the other two stay dark.
function stormFlash(at) {
  const arena = $('#arena');
  const el = document.createElement('div');
  el.className = 'stormflash';
  el.style.setProperty('--fx', `${at.x.toFixed(1)}px`);
  el.style.setProperty('--fy', `${at.y.toFixed(1)}px`);
  arena.appendChild(el);
  const ms = beat(260);
  done(el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: ms, easing: 'ease-out' }), ms).then(() => el.remove());
  arena.animate([{ translate: '0 0' }, { translate: '4px -3px' }, { translate: '-3px 2px' }, { translate: '0 0' }], { duration: beat(240) });
}

async function cairnBolt(u, t) {
  const s = stageBox(u), e = stageBox(t);
  if (!s || !e) return;
  const from = { x: s.x, y: s.top + s.h * CAIRN_CROWN };
  const to = { x: e.x, y: e.top + e.h * 0.45 };
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'bolt storm');
  $('#arena').appendChild(svg);
  // The crown lights before anything leaves it, so the shot reads as coming OUT of the stone.
  pose(u, [{ filter: 'none' }, { filter: 'brightness(2.1) drop-shadow(0 0 12px #8fd2ff)', offset: 0.35 }, { filter: 'none' }], 520);
  /* Reduced motion gets the discharge without the strobe: one bolt, held, no flicker and no shake.
     The point of the effect is that the cairn hit THAT enemy, and a still bolt still says so. */
  const strikes = reduced ? 1 : CAIRN_STRIKES;
  for (let n = 0; n < strikes; n++) {
    const pts = stormPath(from, to, 34);
    const forks = reduced ? [] : [stormFork(pts, 1), stormFork(pts, -1)];
    svg.innerHTML = `<circle class="sb-crown" cx="${from.x.toFixed(1)}" cy="${from.y.toFixed(1)}" r="17"/>
      <polyline class="sb-glow" points="${ptsAttr(pts)}"/>
      <polyline class="sb-body" points="${ptsAttr(pts)}"/>
      ${forks.map((f) => `<polyline class="sb-fork" points="${ptsAttr(f)}"/>`).join('')}
      <polyline class="sb-core" points="${ptsAttr(pts)}"/>`;
    if (reduced) { await wait(260); break; }
    const last = n === strikes - 1;
    /* The strike that carries the hurt is the fat one, and the only one that lights the whole
       arena. Flashing the field on all three puts about ten full-screen flashes a second on the
       screen, which is squarely in the band that sets off photosensitive seizures — and two
       flickers answered by one crack is the better beat regardless. */
    svg.classList.toggle('hard', last);
    const ms = beat(last ? 200 : 120);
    if (last) stormFlash(to);
    await done(svg.animate([{ opacity: 0.3 }, { opacity: 1, offset: 0.25 }, { opacity: 0.65, offset: 0.6 },
      { opacity: 1, offset: 0.8 }, { opacity: last ? 0 : 0.12 }], { duration: ms }), ms);
  }
  svg.remove();
}

/* A beam fired from one fighter to another, bursting where it lands. Purely visual — whatever called
   it has already moved the HP. Three styles share the shape and differ only in wave, colour and what
   they shed and burst into:
     water — Maren's Backwash, a wavy surge that sheds droplets (spellToll)
     fire  — Malgrath's Infernal Toll, a jagged hellfire beam that sheds rising embers (infernalToll)
     blood — Morwenna's Crimson Mend channel, a red link to each ally that bursts as a heal (beginTurn) */
const BEAM = {
  water: { cls: '',           jagged: false, rise: false, impact: 'splash' },
  fire:  { cls: ' hellfire',  jagged: true,  rise: true,  impact: 'fire' },
  blood: { cls: ' bloodlink', jagged: false, rise: false, impact: 'heal' },
};
const bloodLink = (src, t) => backwash(src, t, 'blood');

/* Crimson Mend, standing: while the acting unit has an open blood channel, a vein runs from her to
   every living ally for the whole of her turn — not just the flash of each tick. Called on every
   render, it re-aims the veins at wherever everyone stands now, drops the fallen, and clears itself
   once her turn is over (the bar moves on) or the channel closes. Elements are kept between renders
   so the flowing blood never stutters. */
function syncBloodTethers() {
  const live = !state.moving && !['won', 'lost', 'cleared'].includes(state.phase);
  const m = live ? unitBy(state.active) : null;
  let svg = document.getElementById('bloodTethers');
  if (!m || m.hp <= 0 || !has(m, 'bloodchannel')) { svg?.remove(); return; }
  const s = stageBox(m);
  if (!s) return;
  if (!svg || svg.dataset.uid !== m.uid) {
    svg?.remove();
    svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.id = 'bloodTethers';
    svg.setAttribute('class', `tethers${reduced ? ' still' : ''}`);
    svg.dataset.uid = m.uid;
    svg.innerHTML = '<circle class="tv-src" r="7"/>';
    $('#arena').appendChild(svg);
  }
  const from = { x: s.x + facing(m) * s.w * 0.12, y: s.top + s.h * 0.42 };
  const src = svg.querySelector('.tv-src');
  src.setAttribute('cx', from.x.toFixed(1));
  src.setAttribute('cy', from.y.toFixed(1));
  const allies = alliesOf(m).filter((a) => a.uid !== m.uid);
  const keep = new Set(allies.map((a) => a.uid));
  svg.querySelectorAll('g[data-uid]').forEach((g) => { if (!keep.has(g.dataset.uid)) g.remove(); });
  for (const a of allies) {
    const e = stageBox(a);
    if (!e) continue;
    const to = { x: e.x, y: e.top + e.h * 0.45 };
    const len = Math.hypot(to.x - from.x, to.y - from.y);
    // A vein sags a little between the two, like a cord under its own weight.
    const c = { x: (from.x + to.x) / 2, y: (from.y + to.y) / 2 + Math.min(40, len * 0.18) };
    const d = `M${from.x.toFixed(1)} ${from.y.toFixed(1)} Q${c.x.toFixed(1)} ${c.y.toFixed(1)} ${to.x.toFixed(1)} ${to.y.toFixed(1)}`;
    let g = svg.querySelector(`g[data-uid="${a.uid}"]`);
    if (!g) {
      g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.dataset.uid = a.uid;
      g.innerHTML = '<path class="tv-glow"/><path class="tv-body"/><path class="tv-flow"/><circle class="tv-node" r="4.5"/>';
      svg.insertBefore(g, src);   // her own pulse draws on top of every vein
    }
    g.querySelectorAll('path').forEach((p) => p.setAttribute('d', d));
    const n = g.querySelector('.tv-node');
    n.setAttribute('cx', to.x.toFixed(1));
    n.setAttribute('cy', to.y.toFixed(1));
  }
}

async function backwash(src, u, style = 'water') {
  const b = BEAM[style] || BEAM.water;
  const s = stageBox(src), e = stageBox(u);
  if (reduced || !s || !e) return;
  const from = { x: s.x + facing(src) * s.w * 0.22, y: s.top + s.h * 0.3 };
  const to = { x: e.x, y: e.top + e.h * 0.5 };
  const dx = to.x - from.x, dy = to.y - from.y, len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;  // unit normal: the wave wobbles across the beam
  const pts = [];
  for (let i = 0; i <= 28; i++) {
    const k = i / 28, w = (b.jagged ? (i % 2 ? 1 : -1) * (2 + Math.random() * 4) : Math.sin(k * Math.PI * 5) * 6) * Math.sin(k * Math.PI);
    pts.push(`${(from.x + dx * k + nx * w).toFixed(1)},${(from.y + dy * k + ny * w).toFixed(1)}`);
  }
  const line = pts.join(' ');
  const drops = [0.3, 0.5, 0.7].map((k, i) => {
    const side = i % 2 ? 1 : -1;
    return `<circle cx="${(from.x + dx * k + nx * 9 * side).toFixed(1)}" cy="${(from.y + dy * k + ny * 9 * side).toFixed(1)}" r="2.6"/>`;
  }).join('');
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', `bolt backwash${b.cls}`);
  svg.innerHTML = ['bw-glow', 'bw-body', 'bw-core'].map((c) =>
    `<polyline class="${c}" points="${line}" pathLength="1" stroke-dasharray="1 1" stroke-dashoffset="1"/>`).join('') + drops;
  $('#arena').appendChild(svg);
  const ms = beat(520);
  // The surge races out from Maren to the caster, then the whole beam fades.
  for (const pl of svg.querySelectorAll('polyline')) {
    pl.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0, offset: 0.45 }, { strokeDashoffset: 0 }], { duration: ms, fill: 'forwards' });
  }
  svg.querySelectorAll('circle').forEach((c, i) => c.animate(
    [{ opacity: 0, transform: 'translateY(0)' }, { opacity: 1, offset: 0.25 + i * 0.08 }, { opacity: 0, transform: `translateY(${b.rise ? -14 : 14}px)` }],
    { duration: ms, fill: 'forwards' }));  // droplets and blood fall, embers rise
  setTimeout(() => burst(u, b.impact), ms * 0.45);
  const anim = svg.animate([{ opacity: 1 }, { opacity: 1, offset: 0.6 }, { opacity: 0 }], { duration: ms });
  await done(anim, ms);
  svg.remove();
}

/* EXECUTE'S BLOOD RITE — Vesper's signature in three beats. Purely visual: executeSkill moves the HP.
   bloodGather   thick blood streams arc out of every donor into Vesper, who glows red as a blood orb
                 swells in front of him (his own share pulses straight into it).
   bloodPillar   he throws it all at the sky: a red pillar shoots up from him and off the top of the field.
   bloodTorrent  it pours back down on the target as a torrent of blood light, drops raining down it,
                 and pools at their feet. Resolves as it strikes, so the blow lands under it. */
// A donor's HP bar during the rite: the share they give up stays lit as a bright red chunk where it
// used to be, flashes, then drains away toward the bar's new end as their blood streams over to
// Vesper, and the whole bar pulses red meanwhile. (The fill itself has already dropped.)
function bleedBar(u, from, to, ms) {
  const bar = actorEl(u)?.querySelector('.bar.hp');
  if (!bar || reduced || from <= to) return;
  const chunk = document.createElement('div');
  chunk.className = 'drain';
  const w = `${((from - to) / u.maxHp) * 100}%`;
  chunk.style.left = `${(to / u.maxHp) * 100}%`;
  chunk.style.width = w;
  bar.insertBefore(chunk, bar.querySelector('span'));
  bar.classList.add('bleeding');
  chunk.animate([
    { width: w, opacity: 1, filter: 'brightness(2.2)' },
    { width: w, opacity: 1, filter: 'brightness(1)', offset: 0.12 },
    { width: w, opacity: 0.6, filter: 'brightness(1.8)', offset: 0.24 },
    { width: w, opacity: 1, filter: 'brightness(1)', offset: 0.36 },
    { width: w, opacity: 1, offset: 0.62, easing: 'ease-in' },
    { width: '0%', opacity: 0.5 }], { duration: ms, fill: 'forwards' });
  setTimeout(() => { chunk.remove(); bar.classList.remove('bleeding'); }, ms + 80);
}

function riteSvg(cls, html) {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', `bolt rite ${cls}`);
  svg.innerHTML = html;
  $('#arena').appendChild(svg);
  return svg;
}
// A point on a quadratic curve, for drops that ride the streams.
const quadAt = (a, c, b, k) => ({ x: (1 - k) ** 2 * a.x + 2 * (1 - k) * k * c.x + k * k * b.x, y: (1 - k) ** 2 * a.y + 2 * (1 - k) * k * c.y + k * k * b.y });

async function bloodGather(u, donors) {
  const me = stageBox(u);
  if (reduced || !me) { await castPose(u, true); return; }
  const to = { x: me.x + facing(u) * me.w * 0.18, y: me.top + me.h * 0.4 };
  const streams = donors.filter((a) => a !== u).map(stageBox).filter(Boolean).map((b) => {
    const from = { x: b.x, y: b.top + b.h * 0.45 };
    // Each stream bows up over the line between them, higher the farther it has to travel.
    const c = { x: (from.x + to.x) / 2, y: Math.min(from.y, to.y) - 34 - Math.abs(from.x - to.x) * 0.18 };
    return { from, c, d: `M${from.x.toFixed(1)} ${from.y.toFixed(1)} Q${c.x.toFixed(1)} ${c.y.toFixed(1)} ${to.x.toFixed(1)} ${to.y.toFixed(1)}` };
  });
  const svg = riteSvg('gather', streams.map((st) => ['rt-glow', 'rt-body', 'rt-core']
      .map((k) => `<path class="${k}" d="${st.d}" pathLength="1" stroke-dasharray="1 1" stroke-dashoffset="1"/>`).join('')).join('')
    + streams.map(() => '<circle class="rt-drop" r="3.4"/><circle class="rt-drop" r="2.6"/>').join('')
    + `<circle class="rt-orb" cx="${to.x.toFixed(1)}" cy="${to.y.toFixed(1)}" r="13"/>`
    + `<circle class="rt-orbcore" cx="${to.x.toFixed(1)}" cy="${to.y.toFixed(1)}" r="6"/>`);
  const ms = beat(1300);
  // He rises a little and runs red for the whole rite.
  pose(u, [{ transform: 'none', filter: 'none' },
    { transform: 'translateY(-6px)', filter: 'brightness(1.15) drop-shadow(0 0 10px #d0182c)', offset: 0.2 },
    { transform: 'translateY(-8px)', filter: 'brightness(1.25) drop-shadow(0 0 16px #ff2a3e)', offset: 0.85 },
    { transform: 'translateY(-6px)', filter: 'brightness(1.15) drop-shadow(0 0 12px #d0182c)' }], 1300 + 520);
  // Each stream pours in from its donor, then its tail is drawn into him after it.
  svg.querySelectorAll('path').forEach((pth) => pth.animate([
    { strokeDashoffset: 1 }, { strokeDashoffset: 0, offset: 0.45 }, { strokeDashoffset: 0, offset: 0.62 }, { strokeDashoffset: -1 }],
    { duration: ms, easing: 'ease-in-out', fill: 'forwards' }));
  // Drops ride every stream into him.
  const drops = svg.querySelectorAll('.rt-drop');
  streams.forEach((st, i) => [0, 1].forEach((j) => {
    const frames = Array.from({ length: 11 }, (_, n) => {
      const pt = quadAt(st.from, st.c, to, n / 10);
      return { transform: `translate(${pt.x.toFixed(1)}px, ${pt.y.toFixed(1)}px)`, opacity: n === 0 || n === 10 ? 0 : 1 };
    });
    drops[i * 2 + j].animate(frames, { duration: ms * 0.5, delay: ms * (0.12 + j * 0.2), easing: 'ease-in', fill: 'both' });
  }));
  // The orb swells as the blood arrives.
  for (const o of svg.querySelectorAll('.rt-orb, .rt-orbcore')) o.animate(
    [{ transform: 'scale(.2)', opacity: 0 }, { transform: 'scale(.6)', opacity: 1, offset: 0.4 }, { transform: 'scale(1.25)', opacity: 1 }],
    { duration: ms, easing: 'ease-in', fill: 'forwards' });
  await sleep(ms);
  svg.remove();
}

async function bloodPillar(u) {
  const me = stageBox(u);
  if (reduced || !me) return;
  const x = me.x + facing(u) * me.w * 0.18, y = me.top + me.h * 0.4;
  const col = (w0, w1) => `${(x - w0).toFixed(1)},${y.toFixed(1)} ${(x + w0).toFixed(1)},${y.toFixed(1)} ${(x + w1).toFixed(1)},-40 ${(x - w1).toFixed(1)},-40`;
  const svg = riteSvg('pillar', `<polygon class="rt-glow" points="${col(16, 24)}"/><polygon class="rt-body" points="${col(8, 12)}"/>`
    + `<polygon class="rt-core" points="${col(2.5, 4)}"/>`
    + `<circle class="rt-orb" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="16"/>`);
  const ms = beat(560);
  // It shoots up out of him and off the top of the field, then thins away as it goes.
  svg.animate([
    { clipPath: `inset(0 0 ${(svg.clientHeight - y).toFixed(0)}px 0)`, opacity: 1 },
    { clipPath: 'inset(0 0 0 0)', opacity: 1, offset: 0.45 },
    { clipPath: 'inset(0 0 0 0)', opacity: 0 }], { duration: ms, easing: 'ease-out', fill: 'forwards' });
  svg.querySelector('.rt-orb').animate([{ transform: 'scale(1.25)' }, { transform: 'scale(.3)', opacity: 0 }], { duration: ms * 0.5, fill: 'forwards' });
  tremorFx(320);
  await sleep(ms);
  svg.remove();
}

async function bloodTorrent(t) {
  const e = stageBox(t);
  if (reduced || !e) return;
  const topW = e.w * 0.55, botW = e.w * 0.78, y0 = -10, y1 = e.feet + 2;
  const shaft = (k) => `${(e.x - topW * k).toFixed(1)},${y0} ${(e.x + topW * k).toFixed(1)},${y0} `
    + `${(e.x + botW * k).toFixed(1)},${y1.toFixed(1)} ${(e.x - botW * k).toFixed(1)},${y1.toFixed(1)}`;
  const drops = Array.from({ length: 9 }, (_, i) =>
    `<circle class="rt-drop" cx="${(e.x + (i / 8 - 0.5) * botW * 1.3).toFixed(1)}" cy="${(y1 * (0.15 + (i % 3) * 0.22)).toFixed(1)}" r="${(2.2 + (i % 3) * 0.7).toFixed(1)}"/>`).join('');
  const svg = riteSvg('torrent', `<polygon class="rt-glow" points="${shaft(1.5)}"/><polygon class="rt-body" points="${shaft(1)}"/>`
    + `<polygon class="rt-core" points="${shaft(0.38)}"/>`
    + `<ellipse class="rt-pool" cx="${e.x.toFixed(1)}" cy="${y1.toFixed(1)}" rx="${(botW * 1.7).toFixed(1)}" ry="8"/>` + drops);
  const ms = beat(1100), LAND = 0.26;
  // The torrent pours down out of the sky, holds over them, then drains away.
  svg.animate([
    { clipPath: 'inset(0 0 100% 0)', opacity: 0.95, easing: 'ease-in' },
    { clipPath: 'inset(0 0 0% 0)', opacity: 1, offset: LAND },
    { clipPath: 'inset(0 0 0% 0)', opacity: 1, offset: 0.7 },
    { clipPath: 'inset(0 0 0% 0)', opacity: 0 }], { duration: ms, fill: 'forwards' });
  svg.querySelectorAll('.rt-drop').forEach((c, i) => c.animate(
    [{ opacity: 0, transform: 'translateY(-30px)' }, { opacity: 1, offset: 0.3 }, { opacity: 0, transform: `translateY(${(e.h * 0.5).toFixed(0)}px)` }],
    { duration: ms * 0.6, delay: ms * (0.08 + (i % 4) * 0.07), fill: 'both', easing: 'ease-in' }));
  svg.querySelector('.rt-pool').animate(
    [{ transform: 'scaleX(.2)', opacity: 0 }, { transform: 'scaleX(.2)', opacity: 0, offset: 0.24 }, { opacity: 1, offset: 0.4 }, { transform: 'scaleX(1)', opacity: 0 }],
    { duration: ms, fill: 'forwards' });
  setTimeout(() => svg.remove(), ms + 60);
  // Only once the torrent has reached the ground under them (plus a breath) does the blow land.
  await sleep(ms * (LAND + 0.06));
  tremorFx(420);
}

/* SACRED LIGHT — Sister Liesl's mend: a shaft of dawn opens high over the ally and pours straight
   down onto them, pooling where they stand. Purely visual — healSkill moves the HP. The await
   returns once the light has landed, so the heal number pops while the shaft still stands. */
async function sacredLight(t) {
  const e = stageBox(t);
  if (reduced || !e) return;
  const topW = e.w * 0.5, botW = e.w * 0.68, y0 = -8, y1 = e.feet + 2;
  // Three nested shafts, each a slim trapezoid from above the sky edge down to the ally's feet.
  const shaft = (k) => `${(e.x - topW * k).toFixed(1)},${y0} ${(e.x + topW * k).toFixed(1)},${y0} `
    + `${(e.x + botW * k).toFixed(1)},${y1.toFixed(1)} ${(e.x - botW * k).toFixed(1)},${y1.toFixed(1)}`;
  const motes = [-1, 0, 1].map((side, i) =>
    `<circle cx="${(e.x + side * e.w * 0.26).toFixed(1)}" cy="${(y1 * (0.35 + i * 0.18)).toFixed(1)}" r="2.4"/>`).join('');
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'bolt sacredlight');
  svg.innerHTML = `<polygon class="sl-glow" points="${shaft(1.5)}"/><polygon class="sl-body" points="${shaft(1)}"/>`
    + `<polygon class="sl-core" points="${shaft(0.45)}"/>`
    + `<ellipse class="sl-pool" cx="${e.x.toFixed(1)}" cy="${y1.toFixed(1)}" rx="${(botW * 1.6).toFixed(1)}" ry="7"/>` + motes;
  $('#arena').appendChild(svg);
  const ms = beat(950);
  // The shaft sweeps down out of the sky, holds while the mend lands, then lifts away.
  svg.animate([
    { clipPath: 'inset(0 0 100% 0)', opacity: 0.9 },
    { clipPath: 'inset(0 0 0% 0)', opacity: 1, offset: 0.22 },
    { clipPath: 'inset(0 0 0% 0)', opacity: 1, offset: 0.72 },
    { clipPath: 'inset(0 0 0% 0)', opacity: 0 },
  ], { duration: ms, easing: 'ease-out', fill: 'forwards' });
  // Light motes drift down the shaft; the pool spreads where it strikes the ground.
  svg.querySelectorAll('circle').forEach((c, i) => c.animate(
    [{ opacity: 0, transform: 'translateY(-14px)' }, { opacity: 1, offset: 0.3 + i * 0.12 },
     { opacity: 0, transform: 'translateY(14px)' }], { duration: ms, fill: 'forwards' }));
  svg.querySelector('.sl-pool').animate(
    [{ transform: 'scaleX(.25)', opacity: 0 }, { opacity: .9, offset: .35 }, { transform: 'scaleX(1)', opacity: 0 }],
    { duration: ms, fill: 'forwards' });
  setTimeout(() => svg.remove(), ms + 60);
  await sleep(ms * 0.4);
}

// Positions every icon on the speed bar. ms = glide time for this move.
// Losing ground (Fear, a drag): the icon turns tail and runs back down the bar at a readable pace,
// rather than snapping. Only knock-backs set u.recoil — the trip home after acting is not a flight.
const FLEE_MS = 900;
function renderTrack(ms) {
  for (const u of allUnits()) {
    const el = $(`#tok-${u.uid}`);
    if (!el) continue;
    const flee = u.recoil && u.hp > 0;
    if (u.recoil) u.recoil = false;
    el.style.setProperty('--dur', `${Math.round(flee ? FLEE_MS : ms)}ms`);
    if (flee && !reduced) {
      el.classList.remove('flee'); void el.offsetWidth; el.classList.add('flee');
      clearTimeout(el.fleeT);
      el.fleeT = setTimeout(() => el.classList.remove('flee'), FLEE_MS);
    }
    el.style.setProperty('--x', ((u.pos || 0) / TRACK * 100).toFixed(2));
    const isFrozen = hardFrozen(u), isSlow = !!has(u, 'slow');
    const isStagger = staggerPhase(u) != null, halted = staggerStopped(u);
    el.classList.toggle('frozen', isFrozen || pinned(u) || !!has(u, 'bash') || buried(u));
    el.classList.toggle('stagger', isStagger && !isFrozen);
    el.classList.toggle('halt', halted && !isFrozen);
    el.classList.toggle('slow', isSlow && !isFrozen && !isStagger);
    el.classList.toggle('down', (u.grindShown ?? u.hp) <= 0);   // mid-grind a fatal blow is not shown until its last tick
    el.classList.toggle('silenced', !!has(u, 'silence') && u.hp > 0);
    el.classList.toggle('hastened', !!has(u, 'haste') && u.hp > 0);
    el.classList.toggle('acting', state.active === u.uid && !state.moving && !['won', 'lost', 'cleared'].includes(state.phase));
    const st = el.querySelector('.st');
    // Rooted shows no speed-bar label: the token still races to the gate, so it isn't "held" like a
    // Bash or a Stun — the 🌿 Rooted chip above the unit says why it can only act in place.
    const label = isFrozen ? (has(u, 'overheat') ? 'Overheated' : 'Stunned') : pinned(u) ? 'Pinned'
      : has(u, 'bash') ? 'Bashed' : buried(u) ? 'Burrowed' : isStagger ? (isSlow ? 'Staggered + Slow' : 'Staggered') : isSlow ? 'Slowed' : '';
    st.hidden = !label;
    st.textContent = label;
    el.setAttribute('aria-label', `${u.side === 'p' ? 'Your' : 'Enemy'} ${u.name}${label ? `, ${label.toLowerCase()}` : ''}`);
  }
}

/* QUICKENING STONE on the bar (totemPulse): the stone's token flares blue-white and every token it
   shoved slides up the bar behind a slipstream spanning exactly the ground gained — the push is the
   whole of what this stone does, and it happens HERE, on the bar, not on the field. The pos change
   is already made by the caller; this only shows it. The slide is beat-scaled where the bar's other
   glides are raw ms, so the trail is not cut short mid-stride when the clock moves everyone next.
   Reduced motion keeps the position update and drops the decoration. */
const QS_SLIDE_MS = 700;
function quickeningSurge(stone, pushed) {
  const track = $('#track');
  if (reduced || !track) { renderTrack(300); return; }
  const ms = Math.round(beat(QS_SLIDE_MS));
  const flare = $(`#tok-${stone.uid}`);
  if (flare) {
    flare.classList.remove('qflare'); void flare.offsetWidth; flare.classList.add('qflare');
    clearTimeout(flare.qfT); flare.qfT = setTimeout(() => flare.classList.remove('qflare'), 950);
  }
  const len = track.clientWidth * TOTEM_HASTE_PUSH / TRACK;
  for (const a of pushed) {
    const el = a.hp > 0 && $(`#tok-${a.uid}`);
    if (!el) continue;
    el.style.setProperty('--qlen', `${len.toFixed(1)}px`);
    el.style.setProperty('--qdur', `${ms + 350}ms`);
    el.classList.remove('qtrail'); void el.offsetWidth; el.classList.add('qtrail');
    clearTimeout(el.qtT); el.qtT = setTimeout(() => el.classList.remove('qtrail'), ms + 400);
  }
  renderTrack(ms);
}

function passiveText(u) {
  if (u.summon) return `<b>Summon.</b> ${SUMMONS[u.id].desc}`;
  if (u.monster) {
    const m = MONSTERS[u.id];
    return `${m.lore}${m.passive ? `<span class="cpas">${skillIcon(m.passive)}<span><b>Passive · ${m.passive.name}:</b> ${m.passive.desc}</span></span>` : ''}`;
  }
  const weather = favored(u) ? ` <b>${WEATHER[wx()].name}</b> favors this champion.` : '';
  // Every passive in this champion's loadout (their own and any generic ones).
  const c = charById(u.id);
  const list = (u.passives || ['own']).map((id) => passiveById(c, id)).filter(Boolean);
  const own = list.map((ps) => `<span class="cpas">${skillIcon(ps)}<span><b>Passive · ${ps.name}:</b> ${ps.desc}</span></span>`).join('');
  // A champion's Nature rides along whatever passive is equipped — nothing swaps it away.
  // Covering Fire shows its live count of the field's turns beside the text.
  const nature = c.nature ? `<span class="cpas nat">${skillIcon(c.nature)}<span><b>Nature · ${c.nature.name}:</b> ${c.nature.desc}${u.watch ? ` (${u.watchN || 0}/${u.watch})` : ''}</span></span>` : '';
  return factionPassive(u) + weather + own + nature;
}

function factionPassive(u) {
  const f = FACTIONS[u.faction];
  if (runsHot(u)) {
    const sear = contactBurn(u);
    if (soaked(u)) return `<b>Heat ${u.heat}/100 · Soaked:</b> the water keeps the Heat doused at 0 until the Soaked wears off.`;
    return `<b>Heat ${u.heat}/100:</b> +${Math.round(u.heat / 2.5)}% damage. Overheat bar ${heatTier(u)}/4${sear ? `, sears contact for ${sear}` : ''}. Overheats at 100.`;
  }
  if (u.faction === 'orc') return `<b>Rage:</b> +${Math.round(50 * (1 - u.hp / u.maxHp))}% damage from missing HP.`;
  if (u.faction === 'human') {
    const last = u.lastAction ? skillsOf(u).find((s) => s.id === u.lastAction)?.name : null;
    return `<b>Discipline:</b> +${Math.round(disciplineBonus() * 100)}% if you don't repeat your last action${last ? ` (${last})` : ''}.`;
  }
  if (u.race === 'elf') return `<b>Precision ${u.stacks}/${stackCap(u)}:</b> +${u.stacks * 10}% crit. ${charNat(u).line ? 'A hit costs one stack.' : 'Resets when hit.'}`;
  if (u.race === 'dwarf') return `<b>Fortify ${u.stacks}/${stackCap(u)}:</b> −${u.stacks * 8}% damage taken.`;
  if (u.faction === 'tide') return highTide() ? '<b>High Tide:</b> +25% damage and healing this round.' : '<b>Low Tide.</b> High Tide arrives next round.';
  if (u.faction === 'crimson') return courtStarved(u) ? '<b>Bloodthirst, starved:</b> no lifesteal under Clear Skies.'
    : `<b>Bloodthirst:</b> every hit drains ${wx() === 'moon' ? 40 : 20}% of the damage dealt as HP.`;
  if (u.faction === 'undead') {
    if (undyingOn(u)) {
      const left = u.undyingHits;
      return `<b>Undying:</b> already dead and still standing. ${left > 1 ? `Falls for good after ${left} more instances of damage` : 'The next damage it takes ends it for good'}, and nothing can mend it until then.`;
    }
    return '<b>Undying:</b> the blow that would fell it leaves it standing instead — dead on its feet until one more instance of damage lands. Healing from spells and potions is halved.';
  }
  return f.rule;
}

// How many status chips a champion wears before the rest are gathered into a "+N" (see the render below).
// Four fits the unit's own width at every size without reaching over the champions either side of them.
const CHIP_MAX = 4;
function passiveChips(u) {
  const c = [];
  if (u.faction === 'orc') { const r = Math.round(50 * (1 - u.hp / u.maxHp)); if (r > 0 && u.hp > 0) c.push(`Rage +${r}%`); }
  if (u.race === 'elf' && u.stacks) c.push(`Precision ${u.stacks}`);
  if (u.race === 'dwarf' && u.stacks) c.push(`Fortify ${u.stacks}`);
  if (u.faction === 'tide' && highTide() && u.hp > 0) c.push('High Tide');
  if (pv(u).deadScale && u.hp > 0) { const d = deadCount(); if (d) c.push(`Toll +${Math.round(pv(u).deadScale * d * 100)}%`); }
  if (pv(u).killStack && u.hp > 0) { const df = state.teams[u.side === 'p' ? 'e' : 'p'].filter(x => x.hp <= 0 && !x.inert).length; if (df > 0) c.push(`Intent +${Math.round(Math.min(pv(u).killStack.per * df, pv(u).killStack.max) * 100)}%`); }
  if (favored(u) && u.hp > 0) c.push(WEATHER[wx()].name);
  return c;   // labels; the battlefield builds the chips so it can rank and cap them with the statuses
}

function renderBattle() {
  const act = unitBy(state.active);
  const pending = pendingAction(act);
  const targets = pending ? validTargets(act, pending) : [];

  const hunt = huntDepth(), dg = dungeonRun(), exp = expRun();
  $('#tagline').textContent = dg
    ? `${dg.name}, ${dgIsBossRoom() ? 'boss room' : `room ${state.dg.room + 1} of ${dgRooms()}`}. Warband level ${state.level}.`
    : exp ? `${exp.name}, ${expChamber().name}.${expDepth(exp.id) ? ` Descent ${expDepth(exp.id)}.` : ''} Warband level ${state.level}.`
    : hunt ? `${CAVE.name}, ${hunt.name}. Warband level ${state.level}.`
    : `Ashfall Road, battle ${state.battle + 1} of ${state.order.length}. Warband level ${state.level}.`;
  /* Dungeons: the ladder lists the rooms, ending with the boss. The ladder is only on screen
     once a fight is settled (see render), so a win moves the marker on to what comes NEXT
     rather than leaving it on what just fell - on a narrow screen only the marked entry shows
     its name (.ladder li:not(.now) .nm), and "next" is the one worth reading. A loss leaves the
     marker where it is: that is the fight you would retry. */
  const cleared = state.phase === 'won' || state.phase === 'cleared';
  const rung = (i, at, label) => {
    const cls = i < at ? 'done' : i === at ? 'now' : '';
    return `<li class="${cls}"><span class="n">${i + 1}</span><span class="nm">${label}</span></li>`;
  };
  $('#ladder').innerHTML = dg ? (() => {
    const at = state.dg.room + (cleared ? 1 : 0);
    return Array.from({ length: dgRooms() }, (_, i) =>
      rung(i, at, i === DG_ROOM_COUNT ? MONSTERS[dg.boss].name : (dg.roomNames?.[i] || `Room ${i + 1}`))).join('');
  })() : exp || hunt ? '' : (() => {
    const at = state.battle + (cleared ? 1 : 0);
    return state.order.map((k, i) => rung(i, at, FACTIONS[k].name)).join('');
  })();

  // On narrow screens "Round" shortens to "Rd" and High Tide to a wave, so it never runs into the weather pill.
  /* The trailing space lives INSIDE rdFull so the short form closes up to the
     number — "Round 1" when there is room for the word, "R1" when there is not
     and the chip is sitting on the field itself. */
  $('#roundTxt').innerHTML = `<span class="rdFull">Round </span><span class="rdShort">R</span>${state.round}${highTide() ? ' · <b><span class="tideIco" aria-hidden="true">🌊</span><span class="tideTxt">High Tide</span></b>' : ''}`;
  $('#roundTxt').title = highTide() ? 'High Tide' : '';

  const W = WEATHER[wx()], left = roundsUntilWeather();
  const under = hunt || dg || exp;   // caves, dungeons and expeditions have no weather; the cave has the odd earthquake
  const quake = !!hunt && quaking();
  const cond = dg ? dgCond() : null;   // the dungeon's standing condition, where it has one
  const hz = dg ? DG_HAZARDS[dgHazard()] : null;   // Castle Harrowgate: the room's hazard this round
  $('#arena').dataset.wx = under ? 'cave' : wx();
  // Brimstone Fall's warning sky: '2' two rounds out, '1' the round before (see brimstoneOmen).
  $('#arena').dataset.omen = !under && state.nextWeather === 'brim' && left <= 2 ? left : '';
  $('#arena').dataset.dg = dg ? (dg.roomLooks?.[state.dg.room] || dg.look) : exp ? exp.look : '';
  $('#arena').classList.toggle('quake', quaking());
  syncScene();        // the ground this battle is fought on (see THE BATTLEFIELD)
  syncGroundFire();   // Molotov: the flames left burning across one side's ground
  syncUndercutGround();   // Undercut: the blades still under the enemy's ground
  const wxName = quake ? WEATHER.quake.name : hz ? hz.name : cond ? cond.name : under ? (dg ? dg.name : exp ? exp.name : 'Underground') : W.name;
  const wxLeft = quake ? (state.quake === 1 ? 'Last round' : `${state.quake} rounds`) : under ? '' : left === 1 ? 'Last round' : `${left} rounds`;
  $('#wxIcon').textContent = quake ? WX_ICON.quake : hz ? hz.icon : cond ? cond.icon : under ? '🕯️' : WX_ICON[wx()] || '';
  $('#wxName').textContent = $('#wxPopName').textContent = wxName;
  $('#wxLeft').textContent = wxLeft;
  $('#weather').setAttribute('aria-label', `${quake || cond ? 'Condition' : 'Weather'}: ${wxName}${wxLeft ? `, ${wxLeft.toLowerCase().includes('last') ? 'last round' : `${wxLeft} left`}` : ''}. Tap for its effect.`);
  $('#wxFavors').textContent = cond ? dg.name : !under && W.favors ? `Favors the ${FACTIONS[W.favors].name}` : '';
  $('#wxDesc').textContent = quake ? WEATHER.quake.desc : cond ? cond.desc
    : hunt ? 'No weather reaches this deep. Only the dark, the shifting rock and whatever lives in it.'
    : dg ? 'No weather reaches this deep. Only the dark and whatever lives in it.'
    : exp ? 'No weather reaches these chambers. Only the dark and whatever the vault keeps.' : W.desc;
  // When the sky turns, not what it turns into: naming it ahead of time let you plan around a
  // Blood Moon or an Ash Storm before it arrived. The omen sky still warns of Brimstone Fall.
  // A sky bought from the Stray Banner never turns (wxNext is Infinity), so it says so instead of
  // counting down to a round that will not arrive.
  $('#wxNext').innerHTML = under ? ''
    : !Number.isFinite(left) ? 'The sky holds'
    : `The sky turns ${left === 1 ? 'next round' : `in ${left} rounds`}`;

  renderTrack(state.moving ? 400 : 300);

  for (const u of allUnits()) {
    const el = $(`#u-${u.uid}`);
    if (!el) continue;
    // Grudge Axe: held on 1, shown as the 0 it really is. Mid-grind (Limb Shear), the bar shows what the
    // ticks have taken so far, not the blow's full result.
    const hpShown = u.grudge ? 0 : u.grindShown ?? u.hp;
    el.querySelector('.bar.hp .fill').style.width = `${(hpShown / u.maxHp) * 100}%`;
    el.querySelector('.bar.hp span').textContent = u.summon ? `${hpShown}`   // a summon's short bar only has room for what is left
      : u.inert && u.attach !== 'anchor' ? `${hpShown} / ${u.maxHp} blows` : `${hpShown} / ${u.maxHp}`;
    el.querySelector('.lvl').textContent = unitLevelText(u);
    // Covering Fire countdown (Mara): turns left on the field until her free shot. 0 = it's owed, and
    // goes off the moment she is free to take it (not frozen, coffined or bashed).
    const dial = u.watch && el.querySelector('.watchdial');
    if (dial) {
      const left = Math.max(0, u.watch - (u.watchN || 0));
      dial.querySelector('b').textContent = left;
      dial.style.setProperty('--fill', `${Math.min(1, (u.watchN || 0) / u.watch) * 360}deg`);
      dial.classList.toggle('ready', left <= 1);
      dial.title = left ? `Covering Fire in ${left} turn${left === 1 ? '' : 's'}` : 'Covering Fire is owed: it fires as soon as she is free';
    }
    // Storm Cairn: Revs left until its shock, on the same dial (it shocks when stacks reaches a multiple).
    const cairnDial = u.id === 'tot_shock' && el.querySelector('.watchdial');
    if (cairnDial) {
      const done = (u.stacks || 0) % TOTEM_SHOCK_REVS, left = TOTEM_SHOCK_REVS - done;
      cairnDial.querySelector('b').textContent = left;
      cairnDial.style.setProperty('--fill', `${(done / TOTEM_SHOCK_REVS) * 360}deg`);
      cairnDial.classList.toggle('ready', left === 1);
      cairnDial.title = `Shocks in ${left} Rev${left === 1 ? '' : 's'}`;
    }
    el.classList.toggle('frozen', hardFrozen(u) || staggerStopped(u));
    const heat = el.querySelector('.bar.heat');
    if (heat) {
      heat.querySelector('.fill').style.width = `${u.heat}%`;
      heat.querySelector('span').textContent = `Heat ${u.heat}`;
    }
    // Heat aura: a red-orange glow that grows and reddens as a Mech builds Heat (0 for everyone else).
    const hot = (runsHot(u) && !u.summon && u.hp > 0) ? u.heat : 0;
    el.style.setProperty('--heat-glow', (hot / 100).toFixed(2));
    el.classList.toggle('overheating', hot >= 75);
    const mpBar = el.querySelector('.bar.mp');
    if (mpBar) {
      mpBar.querySelector('.fill').style.width = `${(u.mp / u.maxMp) * 100}%`;
      mpBar.querySelector('span').textContent = `${u.mp} / ${u.maxMp} MP`;
    }
    /* STATUS CHIPS. The icon stays put; the label sits in .txt so it can fade away (see .unit .chip .txt).
       Late in a fight a champion can carry a dozen statuses at once, and left to itself the block wraps
       into row after row. The rows grow UPWARD from the feet, so a well-cursed champion ends up wearing
       a wall of text that buries whoever stands behind them. So the row never wraps and never runs past
       CHIP_MAX: what demands an answer comes first (the bad, then the good, then the passive auras,
       which are the most decorative and the widest), and the remainder is gathered into one "+N" that
       names them on hover. */
    const chips = el.querySelector('.chips');
    chips.style.setProperty('--chipAge', `${-(Date.now() - (u.chipsAt || 0))}ms`);
    const dur = (e) => (e.charges != null ? ` ×${e.charges}` : e.until != null || e.turns >= 99 ? '' : ` ${e.turns}`);
    const rank = { bad: 0, neutral: 1, good: 2 };
    const borne = [...u.effects].sort((a, b) => (rank[FX[a.id].kind] ?? 3) - (rank[FX[b.id].kind] ?? 3))
      .map((e) => ({ name: FX[e.id].label,
        html: `<li class="chip ${FX[e.id].kind}"><span class="ico">${fxIco(e.id)}</span><span class="txt">${FX[e.id].label}${dur(e)}</span></li>` }));
    const auras = passiveChips(u).map((t) => ({ name: t, html: `<li class="chip pass">${t}</li>` }));
    const all = [...borne, ...auras];
    const over = all.length - CHIP_MAX;
    chips.innerHTML = (over > 0 ? all.slice(0, CHIP_MAX) : all).map((c) => c.html).join('')
      + (over > 0 ? `<li class="chip more" title="${all.slice(CHIP_MAX).map((c) => c.name).join(', ')}">+${over}</li>` : '');
    syncStatusFx(el, u);
    el.classList.toggle('winding', !!u.windup);
    el.classList.toggle('frenzied', !!u.frenzy);   // Blood Frenzy: his axes run red while it lasts
    el.classList.toggle('lookW', looksWest(u));    // mirrored by where they LOOK, not whose side they fight for
    el.classList.toggle('misted', !!has(u, 'evade')?.mist && u.hp > 0);   // Vesper, gone to mist
    el.classList.toggle('bearing', !!has(u, 'shieldbearer') && u.hp > 0);  // Garrick, shield up for a ward
    el.classList.toggle('disarmed', !!has(u, 'disarmed') && u.hp > 0);
    el.classList.toggle('bashed', !!has(u, 'bash') && u.hp > 0);
    el.classList.toggle('blinded', !!has(u, 'blind') && u.hp > 0);
    el.classList.toggle('mending', !!has(u, 'regen') && u.hp > 0);
    el.classList.toggle('empowered', !!has(u, 'empower') && u.hp > 0);
    el.classList.toggle('charmed', !!has(u, 'immune') && u.hp > 0);
    el.classList.toggle('hastened', !!has(u, 'haste') && u.hp > 0);
    el.classList.toggle('leaking', !!has(u, 'leak') && u.hp > 0);
    syncWardArt(el, u);                                                     // ...and his shield is drawn lit
    syncHeldWeapon(el, u);                                                  // ...and everyone holds the weapon they racked
    el.classList.toggle('down', (u.grindShown ?? u.hp) <= 0);   // mid-grind a fatal blow is not shown until its last tick
    el.classList.toggle('acting', state.active === u.uid && !state.moving && !['won', 'lost', 'cleared'].includes(state.phase));
    // The Pale Host's Undying stand, and Mortessa's coffin: both are states you need to see at a glance.
    el.classList.toggle('undying', undyingOn(u));
    el.classList.toggle('boxed', inBox(u));
    el.classList.toggle('buried', buried(u));
    // THE BUNKER, both halves: the machine braced in its anchor rig, the ally ducked behind the
    // parapet. State classes like buried above — bunkerSkill plays the slam, these hold the look.
    el.classList.toggle('bunkered', u.hp > 0 && bunkered(u));
    el.classList.toggle('lee', u.hp > 0 && !!has(u, 'sheltered'));
    el.classList.toggle('coverCall', u.hp > 0 && bunkered(u) && coverCalls(u));   // the arrow: "you can hide in here"
    el.classList.toggle('taunting', u.hp > 0 && (!!has(u, 'taunt') || !!has(u, 'provoke')));   // the big badge (TAUNT_MARK)
    el.classList.toggle('aloft', aloft(u));   // Skyward Smash: up there, and not to be reached
    el.classList.toggle('apart', apart(u));   // Come Apart: he is not on the field to be seen or struck
    el.classList.toggle('fenced', u.hp > 0 && !!has(u, 'protected'));   // the graveyard fence stands before them
    el.classList.toggle('grudge', !!u.grudge);   // Grudge Axe: on 0 HP, outlined in red, one throw left
    // Barrow's Graveyard Fence is the very railing he carries: while it stands before anyone on his
    // side (only that skill gives Protected), his off hand is empty; it comes back when the fence falls.
    el.classList.toggle('fenceOut', lookOf(artOf(u))?.offhand === 'gravefence' && state.teams[u.side].some((a) => a.hp > 0 && has(a, 'protected')));
    el.classList.toggle('planted', !!u.planted);
    el.classList.toggle('pinned', u.hp > 0 && pinned(u));   // Last Rites: the two iron crosses stand over it   // Mordrek with his cross in the ground: no weapon in hand
    const tgt = targets.includes(u);
    el.classList.toggle('targetable', tgt);
    document.body.classList.toggle('picking', targets.length > 0);   // non-targets let the tap through (see HIT BOXES)
    el.classList.toggle('ally', tgt && (pending.target === 'ally' || pending.target === 'deadAlly'));
    el.tabIndex = tgt ? 0 : -1;
    el.setAttribute('role', tgt ? 'button' : 'group');
    el.setAttribute('aria-label', `${u.side === 'p' ? 'Your' : 'Enemy'} ${u.name}, ${u.hp} of ${u.maxHp} HP`);
  }

  // Command deck. It shows YOUR champion and stays on them through everyone else's turns, so it
  // never jumps about. Tap another fighter to look at theirs (onUnit -> state.inspect); tap your own
  // to come back. When a turn that takes your orders comes up, it goes back on its own (and in a
  // spar where you command someone else, it shows whoever is waiting on you).
  if (state.phase === 'choose') {
    if (state.inspectTurn !== state.active) { state.inspect = null; state.chipsOn = null; state.inspectTurn = state.active; }
  } else state.inspectTurn = null;
  const mine = state.teams.p.find((x) => x.you);
  const d = (state.inspect && unitBy(state.inspect)) || (state.phase === 'choose' ? act : mine) || act;
  const acts = $('#acts');
  // Light the deck up whenever the game is waiting on you ('choose' only ever means your champion).
  $('.deck').classList.toggle('your-turn', state.phase === 'choose' && d === act);
  for (const u of allUnits()) $(`#u-${u.uid}`)?.classList.toggle('viewing', !!state.inspect && u === d);
  for (const u of allUnits()) $(`#u-${u.uid}`)?.classList.toggle('chipsOn', state.chipsOn === u.uid);
  renderSatchel(d);
  if (!d || ['won', 'lost', 'cleared'].includes(state.phase) && !act) {
    const over = ['won', 'lost', 'cleared'].includes(state.phase);
    $('#dName').textContent = !over ? 'Get ready' : state.phase === 'lost' ? 'Defeated' : 'Victory';
    $('#dPassive').innerHTML = over ? '' : 'Everyone is racing to the <b>Act</b> gate. The first to reach it takes the first turn.';
    acts.innerHTML = '';
    acts.dataset.uid = '';
    $('#prompt').hidden = true;
    return;
  }
  // Your champion shows the name you gave them beside the champion they are; when you kept the
  // champion's own name, that read "Sawtooth · Sawtooth", so only say it once.
  const own = d.summon || d.monster ? null : charById(d.id).name;
  $('#dName').textContent = !own ? d.name : d.you && d.name !== own ? `${d.name} · ${own}` : own;
  $('#dPassive').innerHTML = passiveText(d);
  /* The landscape action bar is one line tall and has nowhere to put the
     passive text, so it hangs it on the name instead of losing it. Set here
     rather than in CSS because only this function knows what it says. */
  $('.dhead').title = $('#dPassive').textContent.replace(/\s*Passive ·\s*/g, '\n').trim();

  // Only the fighter whose turn it is can be ordered; anyone else's deck is there to read.
  const orders = d === act && commandable(act);
  const skills = skillsOf(d);
  /* The deck's buttons are cached, and the cache key has to be the KIT and not
     just the unit. It used to be the uid alone, which held while a champion's
     actions were fixed for the whole battle — but Bulwark's Bunker swaps its
     own kit mid-fight (anchored, it may only Stand Up or Guard), and so does
     the ally it shelters. With a uid-only key the old buttons survived, the
     lookup below found no skill behind one of them, and renderBattle threw on
     `s.id` of undefined — the deck, and with it the whole frame, stopped. */
  const kitKey = `${d.uid}|${skills.map((s) => s.id).join(',')}`;
  if (acts.dataset.kit !== kitKey) {
    // Keys 1–5 still follow the loadout order (skillsOf), wherever the button sits.
    const btn = (s, i) => `<span class="actw">
      <button class="act" type="button" data-id="${s.id}" title="${escHTML(`${s.name}: ${s.desc}`)}" aria-label="${escHTML(`${s.name}. ${s.desc}`)}">
        <span class="aico">${skillIcon(s)}${s.sig ? '<span class="star" aria-hidden="true">★</span>' : ''}${s.rank ? `<span class="rkb" title="Rank ${s.rank}: ${rankBonusText(s, s.rank)}">R${s.rank}</span>` : ''}${orders ? `<kbd>${i + 1}</kbd>` : ''}<span class="cdn"></span><span class="mpc"></span></span>
        <span class="nm">${s.name}</span>
        <span class="combo" hidden>Discipline +15%</span>
      </button><button type="button" class="ainfo" data-info="${s.id}" aria-label="${escHTML(`About ${s.name}`)}" aria-expanded="false">i</button></span>`;
    const basic = (s) => s.id === 'attack' || s.id === 'guard';
    // Keys still follow the loadout order, so a slot keeps its number wherever it sits.
    const own = skills.map((sk, i) => [sk, i]).filter(([sk]) => !basic(sk));
    const open = `<span class="actw open" aria-hidden="true"><span class="act"><span class="aico"></span></span></span>`;
    acts.innerHTML = `<div class="agroup">${own.map(([sk, i]) => btn(sk, i)).join('')}${open.repeat(Math.max(0, SKILL_SLOTS - own.length))}</div>`;
    $('#basicActs').innerHTML = skills.map((s, i) => (basic(s) ? btn(s, i) : '')).join('');
    acts.dataset.uid = d.uid;
    acts.dataset.kit = kitKey;
  }
  renderSkillTip(d);
  // The whole row, not just #acts: Attack and Guard sit in their own container beside it.
  // [data-id]: the empty slots padding the block out carry no skill to read.
  $('.deckTop').querySelectorAll('.act[data-id]').forEach((b) => {
    const s = skills.find((x) => x.id === b.dataset.id);
    if (!s) return;   // belt and braces: a button the current kit has no skill for is simply left alone
    const cd = d.cooldowns[s.id] || 0;
    const hushed = silenced(d, s), broke = (s.mp || 0) > (d.mp || 0);
    // Blue mana cost on the icon (red when you can't afford it); a cooldown or silence covers the icon.
    // The Court have no mana to spend, so their badge shows the share of current HP the cast
    // will cost instead. It is never unaffordable — bloodCost leaves them standing on 1 HP.
    const blood = d.faction === 'crimson' && s.id !== 'attack' && s.id !== 'guard' && !s.o?.noBlood;
    const mpc = b.querySelector('.mpc');
    mpc.textContent = blood ? `${Math.round((s.sig ? BLOOD_COST.sig : BLOOD_COST.skill) * 100)}%` : s.mp ? s.mp : '';
    mpc.classList.toggle('short', !blood && broke);
    mpc.classList.toggle('blood', blood);
    b.querySelector('.cdn').textContent = hushed ? '🔇' : cd ? cdText(cd) : s.kind === 'execute' && !warbandWhole(d) ? '💀' : '';
    b.disabled = !(state.phase === 'choose' && orders && usable(act, s));
    b.classList.toggle('armed', state.pending === s.id);
    const combo = b.querySelector('.combo');
    combo.hidden = !(d.faction === 'human' && orders && d.lastAction && d.lastAction !== s.id && !cd);
    /* "Discipline +15%" on a 36px tile is four times its width. The floating
       bar gets the number alone — it is the same bonus on every qualifying
       skill, so the word adds nothing a player rereads — and the full phrase
       still goes to the log the turn it lands. */
    const tight = matchMedia('(orientation: landscape) and (max-height: 540px)').matches;
    const pct = Math.round(disciplineBonus() * 100);
    combo.textContent = tight ? `+${pct}%` : `Discipline +${pct}%`;
    combo.title = `Discipline: +${pct}% for not repeating your last action`;
  });
  $('#prompt').hidden = !pending;
  if (pending) {
    // No word about a taunt here: the taunter's own badge says it (.tauntMark, flashTaunt).
    $('#promptTxt').textContent = `${pending.name}: click a highlighted ${pending.target === 'ally' ? 'ally' : pending.target === 'deadAlly' ? 'fallen ally' : 'enemy'}.`;
  }
}

// A skill's details, opened by its (i): name, what kind it is, cooldown and cost, and what it does.
// It belongs to whoever the deck is showing, and closes when the deck moves on to someone else.
function renderSkillTip(d) {
  const tip = $('#skillTip');
  if (state.tipFor !== d?.uid) { state.tipSkill = null; state.tipFor = d?.uid; }
  const s = d && state.tipSkill ? skillsOf(d).find((x) => x.id === state.tipSkill) : null;
  tip.hidden = !s;
  $('.deckTop').querySelectorAll('.ainfo').forEach((b) => b.setAttribute('aria-expanded', String(!!s && b.dataset.info === s.id)));
  if (!s) return;
  const meta = [s.sig ? '★ Signature' : s.id === 'attack' || s.id === 'guard' ? 'Basic' : 'Skill',
    s.cd ? `Cooldown ${s.cd}` : '', s.mp ? `${s.mp} MP` : ''].filter(Boolean).join(' · ');
  tip.innerHTML = `<b>${s.name}</b><small>${meta}</small><p>${s.desc}</p>`;
}

// Backpack row beside the actions: only on your own champion's turn. Keys 6–9 are its four slots.
// The deck is laid out to a fixed shape so it never jumps: a 4 x 2 block of skill slots beside
// Attack and Guard, four item slots under them. Empties are drawn as outlines, not left out.
const SKILL_SLOTS = 8;   // 4 x 2 skills; the item slots are the backpack's PACK_SLOTS

function renderSatchel(act) {
  const mine = !!act && act.you && !sparring() && !['won', 'lost', 'cleared'].includes(state.phase);   // only your champion uses the satchel, and never in a spar
  const pack = mine ? packOf(act.id) : [];
  $('#satchelHint').hidden = !mine;   // your champion's row, empty slots and all; nobody else's
  $('#items').hidden = !mine;
  if (!mine) return;
  const ready = state.phase === 'choose' && !state.itemUsed;
  // Short enough to sit on the name's line: the long form was a row of its own.
  $('#satchelHint').textContent = !pack.some(Boolean) ? 'Backpack empty' : state.itemUsed ? 'Item used' : 'One item a turn';
  // The backpack's slots as they are packed: an item where one is, an outline where none is.
  const open = '<span class="item open" aria-hidden="true"></span>';
  // A reusable piece stays in its slot once used, so it has to SAY it is spent: it reads as wound
  // down for the rest of the fight and cannot be tapped again until the next one (see itemWound).
  $('#items').innerHTML = pack.map((k, i) => {
    if (!k) return open;
    const wound = itemWound(act, k);
    const note = wound ? ' Wound down — it winds again next battle.' : '';
    return `
    <button class="item${state.pending === `item:${k}` ? ' armed' : ''}${wound ? ' spent' : ''}" type="button" data-item="${k}"
      title="${escHTML(`${ITEMS[k].name}: ${ITEMS[k].desc}${note}`)}" aria-label="${escHTML(`${ITEMS[k].name}. ${ITEMS[k].desc}${note}`)}"${ready && !wound ? '' : ' disabled'}>
      <kbd>${i + 6}</kbd><span class="ico">${ITEM_ICON[k]}</span>
    </button>`;
  }).join('');
}

// XP bar for your champion: level, progress to the next level.
function xpBarHTML() {
  const need = xpToNext(heroLevel()), maxed = heroLevel() >= LEVEL_CAP;
  const pct = maxed ? 100 : Math.round(((profile.xp || 0) / need) * 100);
  return `<div class="xpbar" role="img" aria-label="Level ${heroLevel()}, ${profile.xp || 0} of ${need} XP"><div style="width:${pct}%"></div></div>
    <small class="xpnum">Lv ${heroLevel()} · ${maxed ? 'max level' : `${profile.xp || 0} / ${need} XP`}</small>`;
}

// "A, B, C and D"
const listAnd = (xs) => (xs.length < 2 ? xs.join('') : `${xs.slice(0, -1).join(', ')} and ${xs[xs.length - 1]}`);

// XP earned this battle. (A level-up shows in the card's title and the XP bar.)
function rewardHTML() {
  const r = state.reward;
  if (!r) return '';
  let html = `<div class="xpline"><b class="xpgain">+${r.xp} XP</b>${xpBarHTML()}</div>`;
  if (r.kill) html += `<p class="xpkill">${r.kill} XP of that for the ${r.kills === 1 ? 'killing blow' : `${numWord(r.kills)} killing blows`} ${heroName()} landed.</p>`;
  return html;
}

function showEndOverlay() {
  const { phase } = state;
  let kick, title, body, buttons;
  const d = huntDepth(), dg = dungeonRun();
  // Warband health going into the next room (after the short rest).
  const partyHTML = () => `<ul class="dgparty">${state.team.map((id, i) => {
    const c = state.dg.carry[id], u = state.teams.p.find((x) => x.id === id);
    const pct = c && u ? Math.round((c.hp / u.maxHp) * 100) : 100;
    return `<li><span class="mini">${spriteSVG(id)}</span><b>${i === 0 ? heroName() : shortName(charById(id))}</b><span class="hpbar"><span style="width:${pct}%"></span></span><small>${pct}% HP</small></li>`;
  }).join('')}</ul>`;
  if (sparring() && (phase === 'won' || phase === 'lost')) {
    kick = 'Sparring · Training Yard';
    title = phase === 'won' ? 'Your side wins the spar' : 'The other side wins the spar';
    body = `<p>${state.round} round${state.round === 1 ? '' : 's'} on the practice ground. Nothing was won or lost, and everyone walks away healed.</p>`;
    buttons = [
      { label: 'Spar again', primary: true, fn: startSpar },
      { label: 'Change the matchup', fn: () => { toVillage(); state.trainTab = 'spar'; openPlace('train'); } },
      { label: 'Village', fn: toVillage },
    ];
  } else if (dg && phase === 'won' && state.dg.done) {
    const ch = state.dg.chest;
    kick = `Dungeon cleared · ${dg.name}`;
    title = `${MONSTERS[dg.boss].name} falls`;
    body = `<div class="chest"><p class="loot">The chest: +${ch.gold} gold</p>
        <ul>${ch.items.map((t) => `<li>${t}</li>`).join('')}${ch.trinket ? `<li class="first">First clear! A ${TRINKETS[ch.trinket].name} is waiting in your stash.</li>` : ''}</ul></div>
      ${rewardHTML()}
      <p>This run: <b>${state.dg.gold} gold</b> and <b>${state.dg.xp} XP</b> in total.</p>${questNewsHTML()}`;
    buttons = [{ label: 'Village', primary: true, fn: () => { toVillage(); openPlace('gate'); } }];
  } else if (dg && phase === 'won') {
    const next = state.dg.room + 1, bossNext = next === DG_ROOM_COUNT;
    kick = `${dg.name} · room ${state.dg.room + 1} of ${dgRooms()} cleared`;
    title = state.reward.to > state.reward.from ? `${heroName()} reaches level ${state.reward.to}` : 'Room cleared';
    body = `<p class="loot">+${state.goldWon} gold</p>${rewardHTML()}
      <p>Your HP and MP carry over. The fallen get back up at 30%, and everyone catches their breath.</p>${partyHTML()}
      <p>${bossNext ? `Ahead: <b>${MONSTERS[dg.boss].name}</b>. Watch for the warning before its big attack, then Guard or shield up.` : `Ahead: room ${next + 1} of ${dgRooms()}.`}</p>${questNewsHTML()}`;
    buttons = [
      { label: bossNext ? `Face ${MONSTERS[dg.boss].name}` : 'Go deeper', primary: true, fn: () => { state.dg.room++; enterRoom(); } },
      { label: 'Retreat with your loot', fn: retreatDungeon },
    ];
  } else if (dg && phase === 'lost') {
    kick = 'Defeat';
    title = `Your warband falls in ${dg.name}`;
    body = `${rewardHTML()}${questNewsHTML()}<p>The run is over, but you keep everything you earned on the way: <b>${state.dg.gold} gold</b> and <b>${state.dg.xp} XP</b>.</p>`;
    buttons = [{ label: 'Village', primary: true, fn: () => { toVillage(); openPlace('gate'); } }];
  } else if (d && phase === 'won') {
    const { from, to } = state.reward;
    kick = `Hunt won · ${CAVE.name}`;
    const found = state.stoneNews?.length ? `<p class="loot">Found: ${state.stoneNews.join(', ')}</p>` : '';
    title = to > from ? `${heroName()} reaches level ${to}` : `The ${d.name} pack is down`;
    body = `<p class="loot">+${state.goldWon} gold</p>${found}${rewardHTML()}
      <p>Hunt again for a fresh pack, or head back to Cinderhold. Your warband is fully healed either way.</p>${questNewsHTML()}`;
    buttons = [
      { label: 'Hunt again', primary: true, fn: () => startHunt(d.id) },
      { label: 'Village', fn: () => { toVillage(); openPlace('cave'); } },
    ];
  } else if (d && phase === 'lost') {
    kick = 'Defeat';
    title = 'The pack drives you back';
    body = `${rewardHTML()}${questNewsHTML()}<p>Try the same pack again, or retreat to the village. You keep your level, XP, gold, gear and items.</p>`;
    buttons = [
      { label: 'Retry the hunt', primary: true, fn: () => startBattle(true) },
      { label: 'Village', fn: () => { toVillage(); openPlace('cave'); } },
    ];
  } else if (state.mode === 'duel' && phase === 'won') {
    const { from, to } = state.reward, du = state.duel;
    kick = 'Duel won · Proving Grounds';
    title = to > from ? `${heroName()} reaches level ${to}` : `${du.band} yield`;
    body = `<p class="loot">+${state.goldWon} gold — your ${du.stake} stake back, with profit</p>${rewardHTML()}
      <p>The crowd at the fence wants more. Fresh challengers are already warming up, and your warband is fully healed.</p>${questNewsHTML()}`;
    buttons = [
      { label: 'New challengers', primary: true, fn: () => { toVillage(); openPlace('pvp'); } },
      { label: 'Village', fn: toVillage },
    ];
  } else if (state.mode === 'duel' && phase === 'lost') {
    const du = state.duel;
    kick = 'Defeat · Proving Grounds';
    title = `${du.band} take the purse`;
    body = `${rewardHTML()}${questNewsHTML()}<p>The ${du.stake} gold stake is gone, but nothing else: you keep your level, XP, gear and items.</p>`;
    buttons = [
      { label: 'Back to the Proving Grounds', primary: true, fn: () => { toVillage(); openPlace('pvp'); } },
      { label: 'Village', fn: toVillage },
    ];
  } else if (phase === 'won') {
    const { from, to } = state.reward;
    const next = FACTIONS[state.order[state.battle + 1]];
    kick = `Victory · battle ${state.battle + 1} of ${state.order.length}`;
    title = to > from ? `${heroName()} reaches level ${to}` : `Battle ${state.battle + 1} won`;
    body = `<p class="loot">+${state.goldWon} gold</p>${rewardHTML()}${questNewsHTML()}`;
    buttons = [
      { label: `Fight ${theFaction(next)}`, primary: true, fn: () => { state.battle++; startBattle(false); } },
      { label: 'Visit the village first', fn: () => { state.runPending = true; toVillage(); } },
    ];
  } else if (phase === 'cleared') {
    kick = 'Gauntlet cleared';
    title = `All ${state.order.length} factions defeated`;
    body = `<p class="loot">+${state.goldWon} gold, including the ${CLEAR_BONUS} gold clearing bonus</p>${rewardHTML()}
      <p>${listAnd([heroName(), ...state.team.slice(1).map((id) => shortName(charById(id)))])} cleared Ashfall Road.</p>${questNewsHTML()}`;
    buttons = [{ label: 'Village', primary: true, fn: toVillage }];   // the run ends: no new gauntlet from here
  } else if (phase === 'lost') {
    kick = 'Defeat';
    title = `${theFaction(FACTIONS[state.order[state.battle]], true)} win this one`;
    body = `${rewardHTML()}${questNewsHTML()}<p>Retry this battle against the same warband, or head back to the village. Leaving ends this run, but you keep your level, XP, gold, gear and items.</p>`;
    buttons = [
      { label: 'Retry battle', primary: true, fn: () => startBattle(true) },
      { label: 'Village', fn: toVillage },
    ];
  } else return;

  $('#ovKick').textContent = kick;
  $('#ovTitle').textContent = title;
  $('#ovBody').innerHTML = body;
  const btns = $('#ovBtns');
  btns.innerHTML = '';
  for (const b of buttons) {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = `btn${b.primary ? ' primary' : ''}`;
    el.textContent = b.label;
    el.addEventListener('click', () => { $('#overlay').hidden = true; b.fn(); });
    btns.appendChild(el);
  }
  $('#overlay').hidden = false;
  btns.querySelector('.primary')?.focus();
}

/* ==================================================================
   INPUT
   ================================================================== */
$('.deckTop').addEventListener('click', (ev) => {
  const info = ev.target.closest('.ainfo');
  if (info) {   // (i): open this skill's details, or close them if they are already open
    state.tipSkill = state.tipSkill === info.dataset.info ? null : info.dataset.info;
    renderSkillTip(unitBy(state.tipFor));
    return;
  }
  const b = ev.target.closest('.act');
  if (b && !b.disabled) onSkill(b.dataset.id);
});
// A tap anywhere else closes an open skill card.
document.addEventListener('click', (ev) => {
  if (!state.tipSkill || ev.target.closest('.ainfo, #skillTip')) return;
  state.tipSkill = null;
  renderSkillTip(unitBy(state.tipFor));
});
/* A TAP ON OPEN GROUND BRINGS YOUR OWN DECK BACK. Tapping a fighter shows theirs, and tapping your own
   champion used to be the only way home — but a champion hidden in Bulwark's bunker has no model to
   tap, which stranded the player on Bulwark's locked tiles. The field itself is now the way home, and
   it shuts any open status row too. Aiming a skill is left alone: that is put down at its own tile.
   While aiming, the fighters who are not marks take no taps at all (body.picking), so a tap on one
   lands HERE — and if a taunt is what holds the skill, the taunter's badge flares to say who. */
$('#arena').addEventListener('click', (ev) => {
  if (ev.target.closest('.unit, button, a, input, select, [role="dialog"]')) return;
  if (state.pending) {
    const u = unitBy(state.active), sk = state.phase === 'choose' && pendingAction(u), opts = sk ? validTargets(u, sk) : [];
    if (sk && tauntHeld(sk, opts)) flashTaunt(opts);
    return;
  }
  if (['won', 'lost', 'cleared'].includes(state.phase)) return;
  if (state.inspect == null && state.chipsOn == null) return;
  state.inspect = null; state.chipsOn = null;
  renderBattle();
});
for (const side of ['p', 'e']) {
  const el = $(`#side-${side}`);
  el.addEventListener('click', (ev) => { const u = ev.target.closest('.unit'); if (u) onUnit(u.dataset.uid); });
  el.addEventListener('keydown', (ev) => {
    const u = ev.target.closest('.unit');
    if (u && (ev.key === 'Enter' || ev.key === ' ')) { ev.preventDefault(); onUnit(u.dataset.uid); }
  });
}
$('#items').addEventListener('click', (ev) => {
  const b = ev.target.closest('.item');
  if (b && !b.disabled) onItem(b.dataset.item);
});
$('#cancelBtn').addEventListener('click', () => { state.pending = null; render(); });
function setWxPop(open) {
  $('#wxPop').hidden = !open;
  $('#weather').setAttribute('aria-expanded', String(open));
}
$('#weather').addEventListener('click', (ev) => { ev.stopPropagation(); setWxPop($('#wxPop').hidden); });
document.addEventListener('click', (ev) => { if (!$('#wxPop').hidden && !ev.target.closest('#wxPop')) setWxPop(false); });
document.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') setWxPop(false); });
// Run: ask before leaving the fight. Withdrawing ends a gauntlet run (the fight counts for nothing),
// leaves a dungeon with what was earned so far, and closes a spar with nothing won or lost.
$('#abandonBtn').addEventListener('click', () => {
  const dg = dungeonRun();
  const [title, body] = sparring() ? ['Leave the practice ring?', 'The spar ends here. Nothing is won or lost either way.']
    : dg ? ['Withdraw from the dungeon?', `Your warband falls back to the village. Everything earned in ${dg.name} so far is kept, but the run ends here.`]
    : huntDepth() ? ['Withdraw from the hunt?', 'Your warband falls back to the village, and this fight counts for nothing.']
    : state.mode === 'duel' ? ['Withdraw from the duel?', 'You yield the Proving Grounds bout. Your warband returns to the village, and this fight counts for nothing.']
    : ['Withdraw from the battle?', 'Your gauntlet run ends here and your warband returns to the village. This fight counts for nothing.'];
  $('#withdrawTitle').textContent = title;
  $('#withdrawBody').textContent = body;
  $('#withdrawDlg').showModal();
});
$('#withdrawStay').addEventListener('click', () => $('#withdrawDlg').close());
$('#withdrawGo').addEventListener('click', () => {
  $('#withdrawDlg').close();
  state.runPending = false;
  if (dungeonRun()) retreatDungeon(); else toVillage();
});
// Battle speed toggle on the speed bar: 1× → 1.5× → 2×, remembered in this browser. Takes effect from the next motion.
function renderSpeedBtn() {
  const b = $('#speedBtn');
  b.textContent = `${SPEED}×`;
  b.setAttribute('aria-pressed', String(SPEED !== 1));
  const next = SPEEDS[(SPEEDS.indexOf(SPEED) + 1) % SPEEDS.length];
  b.title = `Battle speed ${SPEED}×. Click for ${next}×`;
}
$('#speedBtn').addEventListener('click', () => {
  SPEED = SPEEDS[(SPEEDS.indexOf(SPEED) + 1) % SPEEDS.length];
  try { localStorage.setItem(SPEED_KEY, String(SPEED)); } catch {}
  renderSpeedBtn();
});
renderSpeedBtn();
// Battle log: hide or show it, remembered in this browser.
const LOG_KEY = 'burizza.logHidden';
function setLogHidden(hide) {
  document.body.classList.toggle('logHidden', hide);
  const b = $('#logBtn');
  b.textContent = hide ? 'Show log' : 'Hide log';
  b.setAttribute('aria-expanded', String(!hide));
  b.title = hide ? 'Show the battle log' : 'Hide the battle log';
  // A sim fight hiding the log (?battle&nolog=1) is not a preference — never let it overwrite the real one.
  if (!TEST_MODE) { try { localStorage.setItem(LOG_KEY, hide ? '1' : '0'); } catch {} }
}
$('#logBtn').addEventListener('click', () => setLogHidden(!document.body.classList.contains('logHidden')));
// The landscape weather pill sits just right of the round chip, whose width changes ("R1", "R12", High Tide's wave).
if (typeof ResizeObserver === 'function') {
  new ResizeObserver(() => $('#arena').style.setProperty('--rdw', `${$('#roundTxt').offsetWidth}px`)).observe($('#roundTxt'));
}
/* Hidden until asked for. The fight is the thing worth looking at; the log is
   where you go to find out why something happened, which is a question you ask
   occasionally and not continuously. A player who opens it has said so, and
   that choice is what gets remembered — so the test is "did they turn it ON",
   not "did they turn it off". */
setLogHidden((() => { try { return localStorage.getItem(LOG_KEY) !== '0'; } catch { return true; } })());
// Fast forward: only offered while your champion is down and the fight is still going.
function renderFfwd() {
  const b = $('#ffwdBtn');
  const show = state.screen === 'battle' && youDown() && !['won', 'lost', 'cleared'].includes(state.phase);
  b.hidden = !show;
  b.setAttribute('aria-pressed', String(FFWD && show));
}
$('#ffwdBtn').addEventListener('click', () => { FFWD = !FFWD; renderFfwd(); });
document.addEventListener('keydown', (ev) => {
  if (!$('#overlay').hidden || ev.ctrlKey || ev.metaKey || ev.altKey) return;
  if (state.screen === 'village' && ev.key === 'Escape' && state.place) { state.place = null; render(); return; }
  if (state.screen !== 'battle') return;
  if (ev.key === 'Escape' && state.pending) { state.pending = null; render(); return; }
  const n = parseInt(ev.key, 10);
  if (state.phase === 'choose' && n >= 1 && n <= 5) {
    const s = skillsOf(unitBy(state.active))[n - 1];   // the loadout decides how many actions there are
    if (s) onSkill(s.id);
  }
  const itemIdx = n - 6;   // keys 6-9: the backpack's four slots
  const packed = state.phase === 'choose' && itemIdx >= 0 && itemIdx < PACK_SLOTS && packOf(unitBy(state.active)?.id)[itemIdx];
  if (packed) onItem(packed);
});

/* ==================================================================
   AUTO-BATTLE HARNESS — index.html?battle drops you straight into a
   fight, skipping the village, so a mechanic can be watched the moment
   the page loads. It fights on a throwaway profile (TEST_MODE) and never
   touches the real save. All configuration rides in the query string:

     ?battle                 a quick gauntlet with the default warband
     ?battle&team=wren,garrick,aelira,maren   who stands in the band (slot 0 = you)
     ?battle&foe=tunnels     a cave hunt at that depth instead (tunnels|grotto|den)
     ?battle&vs=barrow,octavia,mogra,hesk   a hand-picked enemy warband (champions, fought as a duel)
     ?battle&auto=1          the AI plays your champion too, so the fight runs hands-off
     ?battle&lv=10           your champion's level (skills unlock with it; default 8)
     ?battle&pas=heroic      force the hero's passive loadout (comma-separated ids)

   Unknown champion ids are dropped; an empty team falls back to the default.
   ================================================================== */
function bootTest(params) {
  TEST_MODE = true;
  AUTO_PLAY = params.has('auto') && params.get('auto') !== '0';   // auto=1: the AI plays your champion too
  SIM_FREE = params.has('free') && params.get('free') !== '0';     // free=1: no cooldowns, full mana, every turn
  EGUARD = params.has('eguard') && params.get('eguard') !== '0';   // eguard=1: enemies only guard
  if (params.has('speed')) SPEED = Math.max(0.1, Math.min(3, +params.get('speed') || 1));  // speed=0.2: 5× slower
  if (params.has('nolog')) setLogHidden(true);                    // nolog=1: all field, no chronicle
  if (params.has('nohud')) document.body.classList.add('noHud');  // nohud=1: arena only, no bars or deck
  /* The Sim Deck runs these fights in frames and needs to know when one is decided so it can deal the
     next. It cannot simply read `state`: that is a module-scope binding and invisible from outside the
     frame. So a test fight publishes a tiny read-only window onto itself - nothing the game uses, and
     nothing that exists outside the harness. */
  window.SIM = {
    get phase() { return state.phase; },
    get round() { return state.round; },
    get over() { return ['won', 'lost', 'cleared'].includes(state.phase); },
  };
  /* The Melee Bench (melee.html) drives the same frames, but it is rehearsing swings rather than
     watching fights: it replays one champion's strike on demand, as often as it likes, at whatever
     pace, with the battle sitting still between takes. Same reason as SIM above — strikePose and
     WEAPON_STRIKES are module-scope and invisible from outside the frame, so the bench cannot reach
     them itself. Read-only apart from play(), and nothing the game itself ever calls. */
  window.MELEE = {
    /* Every melee champion, flagged with what would draw their swing. The bench reads this from
       whichever frame is already up to fill its picker, then reloads that frame on the pick —
       ROSTER is module-scope too, so there is no way to ask before a frame exists. */
    get roster() {
      return ROSTER.filter((c) => c.role === 'melee').map((c) => ({
        id: c.id, name: c.short || c.name, faction: c.faction,
        strikes: Object.keys(WEAPON_STRIKES).filter((k) => k === c.id || k.startsWith(`${c.id}:`)).length,
      }));
    },
    get units() {
      return allUnits().map((u) => ({ uid: u.uid, id: u.id, name: u.name, side: u.side, hp: u.hp }));
    },
    /* What a champion can actually be made to show, and — the point of the bench — WHICH of the two
       systems will draw it. A champion with a pre-rendered attack clip never reaches WEAPON_STRIKES
       at all (playAttack returns first in strikePose), so hand-editing their poses does nothing and
       the bench needs to say so rather than let someone tune keyframes that will never run. */
    moves(uid) {
      const u = unitBy(uid);
      if (!u) return [];
      const a = animOf(u);
      const clip = !!(a && a.attack);
      const out = [{
        id: 'attack', name: 'Attack',
        from: clip ? 'clip' : WEAPON_STRIKES[u.id] ? 'strike' : 'fallback',
      }];
      for (const s of (skillsOf(u) || [])) {
        if (s.id === 'attack' || s.id === 'guard') continue;
        const hasStrike = !!WEAPON_STRIKES[`${u.id}:${s.name}`];
        const hasClip = !!(a && a[`s-${skillSlug(s.name)}`]);
        if (hasStrike || hasClip) out.push({ id: s.id, name: s.name, from: hasClip ? 'clip' : 'strike' });
      }
      return out;
    },
    // The raw keyframes behind one move, so the bench can show what it is you are editing.
    poseOf(uid, name) {
      const u = unitBy(uid);
      if (!u) return null;
      const ws = WEAPON_STRIKES[`${u.id}:${name}`] || (name === 'Attack' && WEAPON_STRIKES[u.id]);
      return ws ? { ms: ws.ms, hit: ws.hit, wpn: ws.wpn, body: ws.body ? ws.body(facing(u)) : null } : null;
    },
    // Replay one swing. fresh=true so a clip restarts rather than resuming mid-flight.
    // Melee champions dash in, swing, then dash back — just like the real battle.
    async play(uid, name, pace = 1) {
      const u = unitBy(uid);
      if (!u) return false;
      const sk = name === 'Attack' ? { id: 'attack', name: 'Attack' }
        : (skillsOf(u) || []).find((s) => s.name === name) || { id: 'x', name };
      if (sk.o?.shadowMatrix) {
        await beginShadowMatrix(u, sk);
        await wait(800 / pace);
        await matrixClonesAppear(u);
        await wait(800 / pace);
        await matrixResolve(u);
        return true;
      }
      const foe = allUnits().find((o) => o.side !== u.side && o.hp > 0) || null;
      const melee = u.role === 'melee' && foe;
      const swing = async () => {
        const trip = melee ? await dashTo(u, [foe], pace) : null;
        await strikePose(u, true, sk, pace, foe);
        if (trip) await dashBack(u, trip);
      };
      await swing(); await cloneStrike(u, sk);
      return true;
    },
    skillInfo(uid) {
      const u = unitBy(uid);
      if (!u) return [];
      return (skillsOf(u) || []).map(s => ({
        id: s.id, name: s.name, desc: s.desc, cd: s.cd || 0,
        mp: s.mp || 0, sig: !!s.sig, kind: s.kind || 'damage',
        slug: skillSlug(s.name),
        cdLeft: Math.ceil(u.cooldowns[s.id] || 0),
        usable: state.phase === 'choose' && usable(u, s),
      }));
    },
    get canAct() { return state.phase === 'choose'; },
    act(name) { const u = unitBy(state.active); if (!u) return; const all = skillsOf(u); const sk = name === 'Attack' ? all.find(s => s.id === 'attack') : name === 'Guard' ? all.find(s => s.id === 'guard') : all.find(s => s.name === name); if (!sk) return; onSkill(sk.id); },
    // prefers-reduced-motion kills every pose, so the bench can warn instead of looking broken.
    get reduced() { return reduced; },
  };
  /* The Skill Lab (lab.html) casts ANY unit's ANY skill at ANY target, on demand. Same bargain as
     SIM and MELEE: doAction and the roster are module-scope, so the lab cannot reach them itself.
     cast() drives the real executor — pose, projectile, damage, statuses, follow-ups — but the
     bench pays no bills: mana is topped up, cooldowns wiped, and the turn-stopping statuses
     cleared first, so a tester is never told no. doAction does not advance the turn queue (its
     caller does), so a lab cast resolves fully and the battle stays where it was. */
  window.LAB = {
    // The whole roster for the lab's champion picker: ROSTER is a top-level const, which does NOT
    // hang off window, so the lab cannot read it across the frame boundary on its own.
    get roster() { return ROSTER.map((c) => ({ id: c.id, name: c.short || c.name })); },
    get units() {
      return allUnits().filter((x) => !x.inert).map((x) => ({
        uid: x.uid, id: x.id, name: x.name, side: x.side, hp: x.hp, maxHp: x.maxHp,
      }));
    },
    skills(uid) {
      const x = unitBy(uid);
      if (!x) return [];
      return skillsOf(x).map((s) => ({
        id: s.id, name: s.name, kind: s.kind,
        // who this skill is FOR, so the lab can pre-pick a sensible target
        tgt: s.kind === 'damage' || s.kind === 'execute' || s.kind === 'anchor' || s.kind === 'jelly' ? 'enemy'
          : s.kind === 'heal' || s.kind === 'revive' ? 'ally'
          : s.target === 'ally' || s.target === 'allAllies' ? 'ally'
          : s.target === 'enemy' ? 'enemy' : 'self',
        aoe: !!(s.o && s.o.aoe) || s.target === 'allAllies',
      }));
    },
    async cast(uid, skillId, tuid) {
      const x = unitBy(uid);
      if (!x || x.hp <= 0) return 'actor gone';
      const sk = skillsOf(x).find((s) => s.id === skillId);
      if (!sk) return 'no such skill';
      const t = tuid ? unitBy(tuid) : null;
      x.mp = x.maxMp || x.mp;
      x.cooldowns = {};
      x.effects = x.effects.filter((e) => !['silence', 'stun', 'bash', 'fear'].includes(e.id));
      await doAction(x, sk, t);
      return true;
    },
  };
  profile = blankProfile();   // a clean slate — the real save on disk is left alone
  profile.level = Math.max(1, Math.min(30, parseInt(params.get('lv'), 10) || 8));

  // The warband: first id is your champion, the rest are recruits. Keep only real ids,
  // then pad up to a full band — the battle launchers bounce to champion-select if the
  // team isn't TEAM_SIZE, which would defeat the whole point of skipping the village.
  const asked = (params.get('team') || '').split(',').map((s) => s.trim()).filter(Boolean).filter((id) => charById(id));
  const band = (asked.length ? asked : ['wren', 'garrick', 'aelira', 'maren']).slice(0, TEAM_SIZE);
  /* An explicit team= is taken at the size given. A bout of two against one is a
     legitimate thing to want to watch, and padding it up to four defeats the point
     of asking. Only the DEFAULT band is filled out to a full warband. */
  if (!asked.length) {
    for (const id of ['wren', 'garrick', 'aelira', 'maren']) { if (band.length >= TEAM_SIZE) break; if (!band.includes(id)) band.push(id); }
    for (const c of ROSTER) { if (band.length >= TEAM_SIZE) break; if (!band.includes(c.id)) band.push(c.id); }
  }
  profile.hero = { id: band[0], name: shortName(charById(band[0])) };
  profile.recruits = band.slice(1);

  // Optional: pin the hero's passive loadout (e.g. pas=heroic to watch Heroic fire).
  const pas = (params.get('pas') || '').split(',').map((s) => s.trim()).filter(Boolean);
  if (pas.length) profile.loadout = { act: autoLoadout(charById(band[0]), profile.level).act, pas };

  buildSelect();
  buildSkills();
  buildVillage();
  syncTeam();

  // Optional: a hand-picked ENEMY warband (vs=ids). Fought as a duel, so the other side is champions
  // (not a monster pack or the random gauntlet), your recruits still act on their own AI, and slot 0 is
  // still you. Same ids on both sides is a mirror match; a shared id is tagged "Rival" on the enemy.
  const vs = (params.get('vs') || '').split(',').map((s) => s.trim()).filter(Boolean).filter((id) => charById(id));
  if (vs.length) {
    const eband = vs.slice(0, +(params.get('teamsize') || TEAM_SIZE));
    // vs= is always explicit, so it is taken at the size given too — one Gorehound
    // alone is a bout, not an under-filled warband waiting to be padded out.
    /* ctl= hands the bout to the Sparring ring's rules instead of a duel's, so you
       can command more than slot 0: 'all' means BOTH warbands stop and wait for your
       orders (hot-seat, either side), 'side' your side only, 'you' just your champion.
       A spar also wins and loses nothing, which is what you want from a test bout. */
    const ctl = params.get('ctl');
    if (ctl && SPAR_CTL.some(([k]) => k === ctl)) {
      state.mode = 'spar';
      state.spar = { p: [...band], e: [...eband], lv: profile.level, ctl };
      state.enemyIds = eband;
      startBattle(true);
      return;
    }
    state.mode = 'duel';
    state.enemyIds = eband;
    state.duel = { name: 'Sim bout', tier: 1, ids: eband, band: `${shortName(charById(eband[0]))}'s warband`,
                   lv: profile.level, scale: 1, stake: 0, pay: 0, xp: 0, lvOff: 0 };
    startBattle(true);
    return;
  }
  // A cave hunt against a named depth, or the faction gauntlet by default.
  const foe = params.get('foe');
  if (foe && depthById(foe)) startHunt(foe);
  else startGauntlet();
}

/* ==================================================================
   BOOT (keeps the current screen if the page is live-updated)
   ================================================================== */
function start(data) {
  // The harness short-circuits a normal boot. Live-update snapshots (data.state)
  // still win, so hot-reloading mid-fight keeps the battle you're watching.
  const qs = (() => { try { return new URLSearchParams(location.search); } catch (err) { return null; } })();
  if (qs && (qs.has('battle') || qs.has('test')) && !(data && data.state)) { bootTest(qs); return; }
  buildSelect();
  buildSkills();
  buildVillage();
  if (data && data.state) {
    // Older snapshots predate the village; give them its defaults.
    state = { place: null, codex: 'factions', tip: 0, forgeHero: null, forgeTab: 'anvil', runPending: false, itemUsed: false, keeperSays: '', folk: state.folk, ...data.state };
    if (!state.nextWeather) state.nextWeather = rollWeather(wx());
    if (state.screen === 'battle') {
      if (state.time == null) {   // saved before the speed bar existed
        state.time = (state.round - 1) * ROUND_TIME;
        for (const u of allUnits()) u.pos = Math.random() * 80;
      }
      buildArena();
      render();
      if (['won', 'lost', 'cleared'].includes(state.phase)) showEndOverlay();
      else if (state.phase !== 'choose') {
        const u = unitBy(state.active);
        if (u && !state.moving) u.pos = 0;
        state.moving = false;
        nextTurn();
      }
      return;
    }
  }
  // Your warband comes from your saved champion and recruits. A new player starts by creating a champion.
  syncTeam();
  grandfatherTraining();   // saves from before the yard opened keep the techniques they already carry
  rackIllegalWeapons();    // saves from before the faction cuts (and the Ironclad's flesh-kit wall) hand back what no longer fits
  fillNewSlots(heroLevel());   // saves from before six-and-two slots fill the ones that are now open
  seedPacks();   // saves from before backpacks: your champion packs what the satchel held
  if (!profile.hero) { state.team = []; state.screen = 'select'; }
  render();
}
// A window-level peek at the fight's phase, so the Sim Deck (a parent frame) can tell when a battle has
// ended — the module-scoped `state` itself is not reachable across frames. Closes over the live `state`.
window.simPhase = () => { try { return state && state.screen === 'battle' ? state.phase : null; } catch (e) { return null; } };
try { window.claude?.hot?.snapshot?.(() => ({ state })); } catch (err) { /* not in a viewer */ }
// Online mode fetches (or seeds) the server profile BEFORE the game builds its
// screens, so everything that reads `profile` sees the account, not the cache.
// `launch` must stay clear of the hot?.ready token: the headless harness slices
// the script at that token's first appearance, which has to remain the last line.
const netReady = NET.on ? netBoot() : Promise.resolve();
const launch = (data) => netReady.finally(() => start(data));
window.claude?.hot?.ready ? window.claude.hot.ready(launch) : launch(window.claude?.hot?.data ?? {});
